#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 2
#define SLEEP_SEC 5
#define VALID_MIN 0
#define VALID_MAX 1

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "gpio-toggle", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < VALID_MIN || val > VALID_MAX) {
            fprintf(stderr, "Error: invalid read value %d\n", val);
            goto cleanup;
        }

        int new_val = (val == VALID_MIN) ? VALID_MAX : VALID_MIN;
        if (gpiod_line_set_value(line, new_val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE, new_val);
        fflush(stdout);

        for (int i = 0; i < SLEEP_SEC && running; i++) {
            sleep(1);
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

// ADS1115 Registers
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

// Config register bits
#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_SINGLE_0 (0x4000)
#define ADS1115_CONFIG_PGA_4_096V (0x0200)
#define ADS1115_CONFIG_MODE_SINGLE (0x0100)
#define ADS1115_CONFIG_DR_128SPS (0x0080)
#define ADS1115_CONFIG_CQUE_NONE (0x0003)

int main() {
    int fd;
    uint16_t config;
    uint16_t raw;
    int16_t signed_raw;
    float voltage;

    // Open I2C bus
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    // Set slave address
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    // Build config: single-shot, AIN0, PGA 4.096V, single-shot mode, 128 SPS, no comparator
    config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V |
             ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    // Write config to config register (2 bytes, MSB first)
    uint8_t config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (write(fd, config_buf, 3) != 3) {
        fprintf(stderr, "Failed to write config to ADS1115: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Wait for conversion (128 SPS -> ~7.8ms, add margin)
    usleep(10000);

    // Read conversion register (2 bytes)
    uint8_t reg = ADS1115_REG_CONVERSION;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to set conversion register pointer: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t read_buf[2];
    if (read(fd, read_buf, 2) != 2) {
        fprintf(stderr, "Failed to read conversion data: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Convert to signed 16-bit
    raw = ((uint16_t)read_buf[0] << 8) | read_buf[1];
    signed_raw = (int16_t)raw;

    // Convert to voltage (PGA 4.096V -> 1 bit = 125 uV)
    voltage = (float)signed_raw * 0.000125f;

    printf("Voltage: %.3f V\n", voltage);

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MLX90614_ADDR 0x5a
#define I2C_DEV "/dev/i2c-1"
#define TA_PTAT_REG 0x06
#define TA_PTAT_LEN 2
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02x failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read reg 0x%02x failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02x: %s\n", MLX90614_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t raw;
        if (i2c_read_reg16(fd, TA_PTAT_REG, &raw) == 0) {
            printf("Raw TA/PTAT: 0x%04x\n", raw);
        } else {
            fprintf(stderr, "Failed to read TA/PTAT.\n");
        }
        if (running) {
            sleep(POLL_INTERVAL_SEC);
        }
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 4
#define GPIO_PIN_2 17

static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static struct gpiod_chip *chip = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line1) {
        gpiod_line_release(line1);
        line1 = NULL;
    }
    if (line2) {
        gpiod_line_release(line2);
        line2 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 1)");
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 2)");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line1, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output (pin 1)");
        cleanup_and_exit(0);
        return 1;
    }

    if (gpiod_line_request_output(line2, "gpio_control", 1) < 0) {
        perror("gpiod_line_request_output (pin 2)");
        cleanup_and_exit(0);
        return 1;
    }

    printf("GPIO %d set to 0\n", GPIO_PIN_1);
    printf("GPIO %d set to 1\n", GPIO_PIN_2);

    cleanup_and_exit(0);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00

// Config: AIN0 single-ended, +/-4.096V, 128 SPS, continuous
#define CONFIG_VALUE 0xC183

int main() {
    int fd;
    char filename[20];
    int16_t raw;
    uint16_t config;
    char reg;
    char buf[2];

    // Open I2C bus 1
    snprintf(filename, sizeof(filename), "/dev/i2c-1");
    fd = open(filename, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set slave address
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Write config register
    config = CONFIG_VALUE;
    buf[0] = (config >> 8) & 0xFF;
    buf[1] = config & 0xFF;
    reg = CONFIG_REG;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write config register address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to write config register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Wait for conversion (128 SPS -> ~7.8ms, add margin)
    usleep(10000);

    // Read conversion register
    reg = CONVERSION_REG;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write conversion register address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to read conversion register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    raw = (int16_t)((buf[0] << 8) | buf[1]);
    printf("Raw ADC value: %d\n", raw);

    close(fd);
    return 0;
}

