#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 255
#define DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or permissions).\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (int i = 0; i <= PWM_RANGE && running; i++) {
            if (gpioPWM(PWM_PIN, i) != 0) {
                fprintf(stderr, "Error: gpioPWM failed at duty cycle %d.\n", i);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("PWM duty cycle: %d/%d\n", i, PWM_RANGE);
            fflush(stdout);
            usleep(DELAY_US);
        }

        for (int i = PWM_RANGE; i >= 0 && running; i--) {
            if (gpioPWM(PWM_PIN, i) != 0) {
                fprintf(stderr, "Error: gpioPWM failed at duty cycle %d.\n", i);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("PWM duty cycle: %d/%d\n", i, PWM_RANGE);
            fflush(stdout);
            usleep(DELAY_US);
        }
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define CHIP_NAME   "gpiochip0"
#define SOUND_SPEED_CM_US 0.0343
#define TIMEOUT_US  100000
#define POLL_US     100

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static long elapsed_us(const struct timespec *start, const struct timespec *end) {
    return (long)(end->tv_sec - start->tv_sec) * 1000000L +
           (end->tv_nsec - start->tv_nsec) / 1000L;
}

static int wait_for_level(struct gpiod_line *line, int level, long timeout_us) {
    struct timespec t0, now;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    while (running) {
        int v = gpiod_line_get_value(line);
        if (v < 0) return -1;
        if (v == level) return 0;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (elapsed_us(&t0, &now) > timeout_us) return 1;
        usleep(POLL_US);
    }
    return -1;
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trig, 0) < 0) return -1;
    usleep(2);
    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) return -1;

    if (wait_for_level(echo, 1, TIMEOUT_US) != 0) return -1;

    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);

    if (wait_for_level(echo, 0, TIMEOUT_US) != 0) return -1;

    clock_gettime(CLOCK_MONOTONIC, &t1);

    long dur = elapsed_us(&t0, &t1);
    if (dur <= 0 || dur > 38000) return -1;

    return (int)((dur * SOUND_SPEED_CM_US) / 2.0);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hcsr04", 0) < 0) {
        fprintf(stderr, "Failed to request trigger as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo, "hcsr04") < 0) {
        fprintf(stderr, "Failed to request echo as input: %s\n", strerror(errno));
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        int dist = measure_distance(trig, echo);
        if (dist < 0) {
            fprintf(stderr, "Error: sensor read failed (device absent or bus error)\n");
            break;
        }
        printf("Distance: %d cm\n", dist);
        fflush(stdout);
        for (int i = 0; i < 60 && running; i++) sleep(1);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x28
#define CONFIG_REG     0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE    4.096
#define SAMPLE_PERIOD  5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int configure_ads1115(int fd) {
    /*
     * Config register (0x01):
     *   Bit 15    OS        = 1 (start conversion)
     *   Bits 14:12 MUX     = 100 (AIN0 vs GND)
     *   Bits 11:9  PGA     = 001 (±4.096 V)
     *   Bit 8      MODE    = 1 (single-shot)
     *   Bits 7:5   DR      = 100 (128 SPS)
     *   Bit 4      COMP_MODE= 0
     *   Bit 3      COMP_POL= 0
     *   Bit 2      COMP_LAT= 0
     *   Bits 1:0   COMP_QUE= 11 (disable comparator)
     * => 0x8483
     */
    return i2c_write_reg16(fd, CONFIG_REG, 0x8483);
}

static int read_ads1115(int fd, float *voltage) {
    uint16_t raw;
    if (i2c_read_reg16(fd, CONVERSION_REG, &raw) < 0)
        return -1;

    int16_t signed_raw = (int16_t)raw;
    *voltage = (float)signed_raw * REF_VOLTAGE / 32768.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (configure_ads1115(fd) < 0) {
        fprintf(stderr, "ADS1115 configuration failed (device may be absent).\n");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float voltage;
        if (read_ads1115(fd, &voltage) < 0) {
            fprintf(stderr, "Read error; continuing.\n");
        } else if (voltage < 0.0f || voltage > REF_VOLTAGE) {
            fprintf(stderr, "Out-of-range reading: %.4f V\n", voltage);
        } else {
            printf("Voltage: %.4f V\n", voltage);
            fflush(stdout);
        }
        sleep(SAMPLE_PERIOD);
    }

    close(fd);
    return EXIT_SUCCESS;
}

