    if (gpiod_line_request_output(line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("GPIO %d initialized as output (low). Press Ctrl+C to exit.\n", GPIO_LINE);
