#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"
#define MEASURE_TEMP_NOHOLD 0xF3
#define READ_TEMP 0xE0
#define CONVERSION_TIMEOUT_MS 100

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temp) {
    uint8_t buf[2];
    int16_t raw;

    if (i2c_write(fd, MEASURE_TEMP_NOHOLD) < 0)
        return -1;

    for (int i = 0; i < CONVERSION_TIMEOUT_MS; i++) {
        if (i2c_read(fd, buf, 2) == 0)
            break;
        usleep(1000);
        if (i == CONVERSION_TIMEOUT_MS - 1) {
            fprintf(stderr, "Temperature conversion timeout\n");
            return -1;
        }
    }

    raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp = (175.72 * raw / 65536.0) - 46.85;

    if (*temp < -40.0 || *temp > 125.0) {
        fprintf(stderr, "Temperature out of range: %.2f\n", *temp);
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    float temperature;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SI7021_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        if (read_temperature(fd, &temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }
        sleep(5);
    }

    if (fd >= 0)
        close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00

/*
 * Config register (16-bit, big-endian on the bus):
 *   Bit 15    OS: 1 = start single conversion
 *   Bits 14:12 MUX: 100 = AIN0 vs GND
 *   Bits 11:9  PGA: 001 = +/-4.096 V
 *   Bit 8      MODE: 1 = single-shot
 *   Bits 7:5   DR: 010 = 128 SPS
 *   Bit 4      COMP_MODE: 0
 *   Bit 3      COMP_POL: 0
 *   Bit 2      COMP_LAT: 0
 *   Bits 1:0   COMP_QUE: 11 = disable comparator
 */
#define CONFIG_VALUE 0xC183

static int i2c_fd = -1;

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int16_t convert_to_signed(uint16_t raw) {
    return (int16_t)raw;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    const char *dev = "/dev/i2c-1";
    int ret = EXIT_FAILURE;

    i2c_fd = open(dev, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", dev, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Write config to start a single conversion on AIN0 vs GND */
    if (i2c_write_reg16(i2c_fd, CONFIG_REG, CONFIG_VALUE) < 0) {
        fprintf(stderr, "Failed to write config register\n");
        goto cleanup;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    uint16_t raw;
    if (i2c_read_reg16(i2c_fd, CONVERSION_REG, &raw) < 0) {
        fprintf(stderr, "Failed to read conversion register\n");
        goto cleanup;
    }

    int16_t signed_val = convert_to_signed(raw);
    printf("AIN0: %d\n", signed_val);
    ret = EXIT_SUCCESS;

cleanup:
    cleanup();
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 6
#define CYCLE_COUNT 256

static const unsigned int pins[NUM_PINS] = {8, 9, 10, 11, 23, 24};

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "led_control", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for GPIO %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (int cycle = 0; cycle < CYCLE_COUNT && running; cycle++) {
        for (int i = 0; i < NUM_PINS; i++) {
            int val = (cycle >> i) & 1;
            if (gpiod_line_set_value(lines[i], val) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for GPIO %u\n", pins[i]);
                goto cleanup;
            }
        }
        printf("Cycle %3d: ", cycle);
        for (int i = 0; i < NUM_PINS; i++)
            printf("GPIO%u=%d ", pins[i], (cycle >> i) & 1);
        printf("\n");
        fflush(stdout);
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

