    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    for (i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", offsets[i]);
            goto cleanup;
        }
    }

    /* Request lines as outputs, initial value LOW */
    for (i = 0; i < 4; i++) {
        ret = gpiod_line_request_output(lines[i], CONSUMER, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %u as output\n", offsets[i]);
            goto cleanup;
        }
    }

    /* Main loop: toggle every 0.1 seconds */
    while (keep_running) {
        for (i = 0; i < 4; i++) {
            ret = gpiod_line_set_value(lines[i], values[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to set line %u\n", offsets[i]);
                goto cleanup;
            }
            printf("GPIO %u: %s\n", offsets[i], values[i] ? "HIGH" : "LOW");
        }
        usleep(DELAY_US);

        /* Toggle values */
        for (i = 0; i < 4; i++) {
            values[i] = !values[i];
        }
    }

cleanup:
    /* Release lines and close chip */
    for (i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

