#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CONSUMER    "hc-sr04"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static int wait_for_level(struct gpiod_line *line, int level, long long timeout_us) {
    long long deadline = now_us() + timeout_us;
    while (now_us() < deadline) {
        int v = gpiod_line_get_value(line);
        if (v < 0) {
            return -1;
        }
        if (v == level) {
            return 0;
        }
        usleep(100);
    }
    return 1;
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo, float *distance_cm) {
    if (gpiod_line_set_value(trig, 0) < 0) {
        return -1;
    }
    usleep(2000);
    if (gpiod_line_set_value(trig, 1) < 0) {
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        return -1;
    }

    if (wait_for_level(echo, 1, 30000) != 0) {
        return 1;
    }

    long long start = now_us();
    if (wait_for_level(echo, 0, 30000) != 0) {
        return 1;
    }
    long long end = now_us();

    long long elapsed = end - start;
    *distance_cm = (float)elapsed / 58.0f;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance;
        int rc = measure_distance(trig, echo, &distance);
        if (rc == 0) {
            printf("Distance: %.2f cm\n", distance);
        } else if (rc == 1) {
            fprintf(stderr, "Error: sensor not responding or out of range.\n");
        } else {
            fprintf(stderr, "Error: GPIO read/write failed.\n");
        }
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

