#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CONSUMER "gpio_control"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[4] = {NULL};
static const int pins[4] = {4, 17, 22, 27};

void cleanup_and_exit(int signum) {
    (void)signum;
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", pins[i]);
            cleanup_and_exit(0);
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", pins[i]);
            cleanup_and_exit(0);
        }
    }

    for (int i = 0; i < 4; i++) {
        if (gpiod_line_set_value(lines[i], 1) < 0) {
            fprintf(stderr, "Failed to set GPIO line %d high\n", pins[i]);
            cleanup_and_exit(0);
        }
        printf("GPIO %d set HIGH\n", pins[i]);
    }

    cleanup_and_exit(0);
    return 0;
}

#include <stdio.h>
