/*
 * DHT11 reader for Raspberry Pi using libgpiod.
 *
 * Wiring:
 *   DHT11 VCC -> 3.3 V (Pin 1)
 *   DHT11 GND -> GND    (Pin 6)
 *   DHT11 DATA-> GPIO4  (Pin 7, BCM 4)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o dht11_libgpiod dht11_libgpiod.c -lgpiod
 *
 * Run:
 *   ./dht11_libgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define DHT11_PIN      4
#define MAX_EDGES      85
#define TIMEOUT_US     200
#define SETTLE_MS      20

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal(int signo, void (*handler)(int))
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(signo, &sa, NULL);
}

/*
 * Wait for the line to reach the requested value, or until TIMEOUT_US elapses.
 * Returns 0 on success, -1 on timeout or error.
 */
static int wait_for_level(struct gpiod_line *line, int level, uint64_t timeout_us)
{
    struct timespec deadline;
    clock_gettime(CLOCK_MONOTONIC, &deadline);
    deadline.tv_sec += timeout_us / 1000000ULL;
    deadline.tv_nsec += (long)((timeout_us % 1000000ULL) * 1000ULL);
    if (deadline.tv_nsec >= 1000000000L) {
        deadline.tv_sec += 1;
        deadline.tv_nsec -= 1000000000L;
    }

    for (;;) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            return -1;
        }
        if (val == level)
            return 0;

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec > deadline.tv_sec ||
            (now.tv_sec == deadline.tv_sec && now.tv_nsec >= deadline.tv_nsec))
            return -1;
    }
}

/*
 * Measure the duration (in microseconds) between two edges of the same level.
 * Returns 0 on success, -1 on timeout or error.
 */
static int measure_edge(struct gpiod_line *line, int level, uint64_t timeout_us,
                        uint64_t *duration_us)
{
    if (wait_for_level(line, level, timeout_us) < 0)
        return -1;

    struct timespec t_start, t_end;
    clock_gettime(CLOCK_MONOTONIC, &t_start);

    if (wait_for_level(line, !level, timeout_us) < 0)
        return -1;

    clock_gettime(CLOCK_MONOTONIC, &t_end);
    *duration_us = (uint64_t)(t_end.tv_sec - t_start.tv_sec) * 1000000ULL +
                   (uint64_t)(t_end.tv_nsec - t_start.tv_nsec) / 1000ULL;
    return 0;
}

/*
 * Read DHT11.
 * Returns 0 on success, -1 on error.
 */
static int read_dht11(struct gpiod_line *line, uint8_t data[5])
{
    memset(data, 0, sizeof(data));

    /* --- Start signal: pull low for >= 1 ms, then high --- */
    if (gpiod_line_request_output(line, "dht11", 0) < 0) {
        fprintf(stderr, "request_output failed: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "set_value(0) failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(1100);
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "set_value(1) failed: %s\n", strerror(errno));
        return -1;
    }

    /* Switch to input; DHT11 may pull low briefly before releasing */
    if (gpiod_line_request_input(line, "dht11") < 0) {
        fprintf(stderr, "request_input failed: %s\n", strerror(errno));
        return -1;
    }

    /* DHT11 response: ~80 us low, ~80 us high */
    if (wait_for_level(line, 0, TIMEOUT_US) < 0) {
        fprintf(stderr, "DHT11 not responding (no low preamble)\n");
        return -1;
    }
    if (wait_for_level(line, 1, TIMEOUT_US) < 0) {
        fprintf(stderr, "DHT11 not responding (no high preamble)\n");
        return -1;
    }

    /* Read 40 data bits */
    uint64_t durations[MAX_EDGES];
    int count = 0;
    for (;;) {
        uint64_t dur;
        if (measure_edge(line, 1, TIMEOUT_US, &dur) < 0) {
            fprintf(stderr, "DHT11 read timeout at bit %d\n", count);
            return -1;
        }
        if (count < MAX_EDGES)
            durations[count] = dur;
        count++;

        if (count >= 80)
            break;
    }

    /* Decode: bit is high if duration > 50 us */
    for (int i = 0; i < 40; i++) {
        int byte_idx = i / 8;
        int bit_idx  = 7 - (i % 8);
        if (durations[2 + i] > 50)
            data[byte_idx] |= (1 << bit_idx);
    }

    /* Checksum */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        fprintf(stderr, "DHT11 checksum mismatch: 0x%02X != 0x%02X\n",
                checksum, data[4]);
        return -1;
    }

    return 0;
}

int main(void)
{
    if (install_signal(SIGINT, sig_handler) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (install_signal(SIGTERM, sig_handler) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DHT11_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle */
    usleep(SETTLE_MS * 1000);

    uint8_t data[5];
    int rc = read_dht11(line, data);

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if (rc < 0)
        return EXIT_FAILURE;

    uint8_t humidity = data[0];
    uint8_t temp_raw  = data[2];
    float temperature = (float)temp_raw;
    float humidity_f  = (float)humidity;

    printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity_f);
    return EXIT_SUCCESS;
}

