#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define NUM_CYCLES 3
#define CYCLE_DELAY_SEC 5

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line1 || !line2) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output line1");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output line2");
        goto cleanup;
    }

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        int val1 = i % 2;
        int val2 = (i + 1) % 2;

        if (gpiod_line_set_value(line1, val1) < 0) {
            perror("gpiod_line_set_value line1");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, val2) < 0) {
            perror("gpiod_line_set_value line2");
            goto cleanup;
        }

        int r1 = gpiod_line_get_value(line1);
        int r2 = gpiod_line_get_value(line2);
        if (r1 < 0 || r2 < 0) {
            fprintf(stderr, "Error reading GPIO values\n");
            goto cleanup;
        }
        if (r1 != val1 || r2 != val2) {
            fprintf(stderr, "Value mismatch: wrote (%d, %d), read (%d, %d)\n",
                    val1, val2, r1, r2);
            goto cleanup;
        }

        printf("Cycle %d: GPIO %d = %d, GPIO %d = %d\n", i + 1,
               GPIO_PIN_1, val1, GPIO_PIN_2, val2);
        fflush(stdout);

        for (int s = 0; s < CYCLE_DELAY_SEC && running; s++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define GPIO_PIN_3 17
#define DELAY_US 100000  /* 0.1 seconds */

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!line1 || !line2 || !line3) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line1, "gpio_control", 0) < 0 ||
        gpiod_line_request_output(line2, "gpio_control", 0) < 0 ||
        gpiod_line_request_output(line3, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* Main loop: toggle every 0.1 seconds */
    while (keep_running) {
        if (gpiod_line_set_value(line1, 1) < 0 ||
            gpiod_line_set_value(line2, 1) < 0 ||
            gpiod_line_set_value(line3, 1) < 0) {
            perror("gpiod_line_set_value HIGH");
            goto cleanup;
        }
        printf("GPIO %d, %d, %d: HIGH\n", GPIO_PIN_1, GPIO_PIN_2, GPIO_PIN_3);
        fflush(stdout);
        usleep(DELAY_US);

        if (!keep_running) break;

        if (gpiod_line_set_value(line1, 0) < 0 ||
            gpiod_line_set_value(line2, 0) < 0 ||
            gpiod_line_set_value(line3, 0) < 0) {
            perror("gpiod_line_set_value LOW");
            goto cleanup;
        }
        printf("GPIO %d, %d, %d: LOW\n", GPIO_PIN_1, GPIO_PIN_2, GPIO_PIN_3);
        fflush(stdout);
        usleep(DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
