#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3

static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static struct gpiod_chip *chip = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line1) {
        gpiod_line_release(line1);
        line1 = NULL;
    }
    if (line2) {
        gpiod_line_release(line2);
        line2 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 1)");
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 2)");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line1, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output (pin 1)");
        cleanup_and_exit(0);
        return 1;
    }

    if (gpiod_line_request_output(line2, "gpio_control", 1) < 0) {
        perror("gpiod_line_request_output (pin 2)");
        cleanup_and_exit(0);
        return 1;
    }

    printf("GPIO %d set to 0\n", GPIO_PIN_1);
    printf("GPIO %d set to 1\n", GPIO_PIN_2);

    cleanup_and_exit(0);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define CONSUMER "gpio_control"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[5];
    unsigned int offsets[5] = {4, 17, 18, 22, 27};
    int values[5] = {0, 0, 0, 0, 0};
    int i;
    int ret;

    /* Register signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines and request them as outputs */
    for (i = 0; i < 5; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", offsets[i]);
            goto cleanup;
        }

        ret = gpiod_line_request_output(lines[i], CONSUMER, values[i]);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %u as output\n", offsets[i]);
            goto cleanup;
        }
    }

    /* Main loop: toggle every 0.05 seconds */
    while (keep_running) {
        for (i = 0; i < 5; i++) {
            values[i] = !values[i];
            ret = gpiod_line_set_value(lines[i], values[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to set line %u\n", offsets[i]);
                goto cleanup;
            }
        }

        for (i = 0; i < 5; i++) {
            printf("GPIO %u: %s\n", offsets[i], values[i] ? "HIGH" : "LOW");
        }
        printf("\n");
        fflush(stdout);

        usleep(50000); /* 0.05 seconds */
    }

cleanup:
    /* Release all lines */
    for (i = 0; i < 5; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
