#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (device absent or permissions)\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Failed to initialise PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        if (gpioPWM(PWM_PIN_1, 128) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_1);
            break;
        }
        if (gpioPWM(PWM_PIN_2, 64) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_2);
            break;
        }
        if (gpioPWM(PWM_PIN_3, 255) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_3);
            break;
        }

        printf("PWM on GPIO %d: 128, GPIO %d: 64, GPIO %d: 255\n",
               PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);
        fflush(stdout);

        usleep(150000);
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

