        goto cleanup;
    }

    /* Main toggle loop */
    for (int i = 0; i < NUM_CYCLES && running; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        int new_val = !val;
        if (gpiod_line_set_value(line, new_val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("Cycle %d: Value set to %d\n", i + 1, new_val);
        fflush(stdout);

        usleep(DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

