#define CONSUMER "gpio_control"
#define DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[9];
    unsigned int offsets[9] = {2, 3, 4, 5, 6, 7, 8, 9, 17};
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < 9; i++) {
        lines[i] = NULL;
    }

    /* Register signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines and request them as outputs, initially low */
    for (i = 0; i < 9; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", offsets[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            perror("gpiod_line_request_output");
            goto cleanup;
        }
    }

    /* Main loop: toggle every line once every 0.05 s */
    while (running) {
        for (i = 0; i < 9; i++) {
            int val = (i % 2 == 0) ? 1 : 0;
            if (gpiod_line_set_value(lines[i], val) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup;
            }
            printf("GPIO %u: %s\n", offsets[i], val ? "HIGH" : "LOW");
        }
        usleep(DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release all lines and close the chip */
    for (i = 0; i < 9; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

