#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define OPT3001_ADDR 0x44
#define REG_RESULT 0x00
#define REG_CONFIG 0x01

int main(void) {
    int fd;
    uint8_t buf[2];
    uint16_t raw;
    float result;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", OPT3001_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    // Write configuration: RN=1111 (16-bit), CT=0, M=11 (previous reading)
    uint16_t config = 0xC800;
    buf[0] = REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to write config register: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    // Read result register
    buf[0] = REG_RESULT;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Failed to write register address: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to read result register: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    raw = (buf[0] << 8) | buf[1];
    result = (float)raw / 100.0f;

    printf("OPT3001 Reading: %.2f\n", result);

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle every 0.5 seconds */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        int new_val = (val == 0) ? 1 : 0;
        ret = gpiod_line_set_value(line, new_val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d: %s\n", GPIO_LINE, new_val ? "HIGH" : "LOW");
        fflush(stdout);

        usleep(500000); /* 0.5 seconds */
    }

    /* Clean up: set line low and release resources */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

