#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_4  4
#define GPIO_PIN_17 17
#define GPIO_PIN_27 27
#define DELAY_US    100000  /* 0.1 seconds */

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3];
    unsigned int offsets[3] = {GPIO_PIN_4, GPIO_PIN_17, GPIO_PIN_27};
    int values[3] = {0, 1, 0};
    int i;
    int ret = EXIT_FAILURE;

    /* Register signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get lines */
    for (i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", offsets[i]);
            goto cleanup;
        }
    }

    /* Request lines as outputs */
    for (i = 0; i < 3; i++) {
        if (gpiod_line_request_output(lines[i], "gpio_control", values[i]) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", offsets[i]);
            goto cleanup;
        }
    }

    /* Main loop */
    while (keep_running) {
        for (i = 0; i < 3; i++) {
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup;
            }
            printf("GPIO %u set to %d\n", offsets[i], values[i]);
        }
        usleep(DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    for (i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 2
#define CYCLE_DELAY 60
#define NUM_CYCLES 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "gpio_toggle", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        int val = (i % 2 == 0) ? 1 : 0;
        if (gpiod_line_set_value(line, val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("Cycle %d: GPIO %d set to %d\n", i + 1, GPIO_LINE, val);
        fflush(stdout);

        for (int s = 0; s < CYCLE_DELAY && running; s++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_5   5
#define GPIO_17  17
#define GPIO_24  24
#define CHIP_NAME "gpiochip0"
#define DELAY_US  200000  /* 0.2 seconds */

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_5 = NULL;
    struct gpiod_line *line_17 = NULL;
    struct gpiod_line *line_24 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line_5 = gpiod_chip_get_line(chip, GPIO_5);
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    line_24 = gpiod_chip_get_line(chip, GPIO_24);
    if (!line_5 || !line_17 || !line_24) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line_5, "gpio_control", 0) < 0 ||
        gpiod_line_request_output(line_17, "gpio_control", 0) < 0 ||
        gpiod_line_request_output(line_24, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* Main loop: toggle every 0.2 seconds */
    while (keep_running) {
        if (gpiod_line_set_value(line_5, 1) < 0 ||
            gpiod_line_set_value(line_17, 1) < 0 ||
            gpiod_line_set_value(line_24, 1) < 0) {
            perror("gpiod_line_set_value HIGH");
            goto cleanup;
        }
        printf("GPIO 5, 17, 24: HIGH\n");
        fflush(stdout);
        usleep(DELAY_US);

        if (!keep_running)
            break;

        if (gpiod_line_set_value(line_5, 0) < 0 ||
            gpiod_line_set_value(line_17, 0) < 0 ||
            gpiod_line_set_value(line_24, 0) < 0) {
            perror("gpiod_line_set_value LOW");
            goto cleanup;
        }
        printf("GPIO 5, 17, 24: LOW\n");
        fflush(stdout);
        usleep(DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line_5)
        gpiod_line_release(line_5);
    if (line_17)
        gpiod_line_release(line_17);
    if (line_24)
        gpiod_line_release(line_24);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

