#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 12
#define PWM_PIN_3 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Failed to initialise PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int duty = 0; duty <= 255 && running; ++duty) {
            for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]) && running; ++i) {
                if (gpioPWM(pins[i], duty) != 0) {
                    fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                    running = 0;
                    break;
                }
            }
            if (running) {
                printf("PWM duty cycle: %d\n", duty);
                fflush(stdout);
                gpioDelay(100000); /* 100 ms */
            }
        }
        for (int duty = 254; duty >= 0 && running; --duty) {
            for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]) && running; ++i) {
                if (gpioPWM(pins[i], duty) != 0) {
                    fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                    running = 0;
                    break;
                }
            }
            if (running) {
                printf("PWM duty cycle: %d\n", duty);
                fflush(stdout);
                gpioDelay(100000); /* 100 ms */
            }
        }
    }

    /* Clean up: turn off PWM and release pigpio */
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

