#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define W1_DIR "/sys/bus/w1/devices/"
#define MAX_GPIO_PINS 3
#define MAX_DEVICE_ID_LEN 20
#define MAX_READ_LEN 256
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int find_ds18b20_device(char *device_id, size_t device_id_len) {
    FILE *fp = popen("ls " W1_DIR, "r");
    if (!fp) {
        fprintf(stderr, "Error: Failed to list w1 devices: %s\n", strerror(errno));
        return -1;
    }

    char line[MAX_DEVICE_ID_LEN];
    int found = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        /* DS18B20 devices have a 16-byte ID starting with '28-' */
        if (strncmp(line, "28-", 3) == 0) {
            size_t len = strlen(line);
            if (len > 0 && line[len - 1] == '\n') line[len - 1] = '\0';
            strncpy(device_id, line, device_id_len - 1);
            device_id[device_id_len - 1] = '\0';
            found = 1;
            break;
        }
    }

    if (pclose(fp) == -1) {
        fprintf(stderr, "Warning: pclose failed: %s\n", strerror(errno));
    }

    if (!found) {
        fprintf(stderr, "Error: No DS18B20 device found under %s\n", W1_DIR);
        return -1;
    }

    return 0;
}

static int read_temperature(const char *device_id, float *temperature) {
    char path[256];
    snprintf(path, sizeof(path), W1_DIR "%s/w1_slave", device_id);

    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open %s: %s\n", path, strerror(errno));
        return -1;
    }

    char line1[MAX_READ_LEN];
    char line2[MAX_READ_LEN];

    if (!fgets(line1, sizeof(line1), fp) || !fgets(line2, sizeof(line2), fp)) {
        fprintf(stderr, "Error: Failed to read from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Verify CRC checksum (line1 contains 'YES' if valid) */
    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "Error: CRC checksum failed for device %s\n", device_id);
        return -1;
    }

    /* Extract temperature from line2 */
    char *temp_str = strstr(line2, "t=");
    if (!temp_str) {
        fprintf(stderr, "Error: Temperature data not found in %s\n", path);
        return -1;
    }

    errno = 0;
    long raw = strtol(temp_str + 2, NULL, 10);
    if (errno != 0) {
        fprintf(stderr, "Error: Failed to parse temperature: %s\n", strerror(errno));
        return -1;
    }

    *temperature = (float)raw / 1000.0f;

    /* Validate temperature range (DS18B20: -55 to +125 C) */
    if (*temperature < -55.0f || *temperature > 125.0f) {
        fprintf(stderr, "Error: Temperature reading out of range: %.2f C\n", *temperature);
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    char device_id[MAX_DEVICE_ID_LEN];

    if (find_ds18b20_device(device_id, sizeof(device_id)) != 0) {
        return 1;
    }

    printf("Found DS18B20 device: %s\n", device_id);

    while (running) {
        float temperature;
        if (read_temperature(device_id, &temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Error: Failed to read temperature.\n");
        }

        /* Sleep in 1-second increments to allow signal handler to interrupt promptly */
        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HTU21D_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"
#define READ_INTERVAL 60

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_measurement(int fd, uint8_t cmd, float *out) {
    uint8_t buf[3];
    ssize_t n;

    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing command 0x%02X: %s\n", cmd, strerror(errno));
        return -1;
    }

    usleep(50000);

    n = read(fd, buf, 3);
    if (n != 3) {
        fprintf(stderr, "Error reading measurement: expected 3 bytes, got %zd (%s)\n", n, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    raw &= 0xFFFC;

    if (raw == 0xFFFF || raw == 0x0000) {
        fprintf(stderr, "Invalid measurement data (0x%04X).\n", raw);
        return -1;
    }

    *out = (float)raw / 16384.0f;
    return 0;
}

int main(void) {
    int fd = -1;
    float temperature, humidity;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", HTU21D_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        if (i2c_read_measurement(fd, 0xE3, &humidity) == 0 &&
            i2c_read_measurement(fd, 0xE3, &temperature) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return 0;
}

