#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define DHT22_PIN 17
#define CONSUMER "dht22_reader"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int level, int timeout_us) {
    int elapsed = 0;
    while (gpiod_line_get_value(line) != level) {
        usleep(1);
        elapsed++;
        if (elapsed > timeout_us) return -1;
    }
    return elapsed;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    int data[5] = {0, 0, 0, 0, 0};
    int i;

    if (gpiod_line_request_output(line, CONSUMER, 1) < 0) return -1;
    usleep(1000);
    gpiod_line_set_value(line, 0);
    usleep(20000);
    gpiod_line_set_value(line, 1);
    usleep(30);

    if (gpiod_line_request_input(line, CONSUMER) < 0) return -1;

    if (wait_for_level(line, 0, 1000) < 0) return -1;
    if (wait_for_level(line, 1, 1000) < 0) return -1;
    if (wait_for_level(line, 0, 1000) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_level(line, 1, 1000) < 0) return -1;
        int high_us = wait_for_level(line, 0, 1000);
        if (high_us < 0) return -1;
        data[i / 8] <<= 1;
        if (high_us > 50) data[i / 8] |= 1;
    }

    if (data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        *hum = (float)((data[0] << 8) + data[1]) / 10.0f;
        *temp = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0f;
        if (data[2] & 0x80) *temp = -*temp;
        return 0;
    }
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temp, hum;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    while (running) {
        if (read_dht22(line, &temp, &hum) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error reading DHT22 (sensor absent or bus error)\n");
            ret = 1;
            break;
        }
        sleep(2);
