#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27

#define PWM_RANGE 255
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int pins[3] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or permissions).\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler.\n");
    }

    while (running) {
        for (int i = 0; i < 3; i++) {
            int val = (i + 1) * 50;
            if (val > PWM_RANGE) val = PWM_RANGE;
            if (gpioPWM(pins[i], val) != 0) {
                fprintf(stderr, "Error: failed to write PWM on GPIO %d.\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("GPIO %d: PWM %d/%d\n", pins[i], val, PWM_RANGE);
        }
        sleep(1);
    }

    for (int i = 0; i < 3; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

