#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line17) {
        perror("gpiod_chip_get_line (17)");
        goto cleanup;
    }
    line18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line18) {
        perror("gpiod_chip_get_line (18)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line17, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (17)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line18, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (18)");
        goto cleanup;
    }

    /* Main loop: toggle every 1 second */
    while (keep_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);
        if (val17 < 0 || val18 < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        int new17 = (val17 == 0) ? 1 : 0;
        int new18 = (val18 == 0) ? 1 : 0;

        if (gpiod_line_set_value(line17, new17) < 0) {
            perror("gpiod_line_set_value (17)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, new18) < 0) {
            perror("gpiod_line_set_value (18)");
            goto cleanup;
        }

        printf("GPIO 17: %d, GPIO 18: %d\n", new17, new18);
        fflush(stdout);

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

