#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 22
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle every 0.5 seconds */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        int new_val = (val == 0) ? 1 : 0;
        ret = gpiod_line_set_value(line, new_val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d: %s\n", GPIO_LINE, new_val ? "HIGH" : "LOW");
        fflush(stdout);

        usleep(500000); /* 0.5 seconds */
    }

    /* Clean up: set line low and release resources */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 255
#define DELAY_US 20000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (device absent or permissions)\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (int i = 0; i <= PWM_RANGE && running; i++) {
            if (gpioPWM(PWM_PIN, i) != 0) {
                fprintf(stderr, "Failed to set PWM duty cycle to %d\n", i);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("PWM duty cycle: %d/%d\n", i, PWM_RANGE);
            fflush(stdout);
            usleep(DELAY_US);
        }
        for (int i = PWM_RANGE; i >= 0 && running; i--) {
            if (gpioPWM(PWM_PIN, i) != 0) {
                fprintf(stderr, "Failed to set PWM duty cycle to %d\n", i);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("PWM duty cycle: %d/%d\n", i, PWM_RANGE);
            fflush(stdout);
            usleep(DELAY_US);
        }
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

