#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_I2C_ADDR 0x29
#define I2C_BUS "/dev/i2c-1"

#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME  0x81
#define TCS34725_CDATA  0x8C
#define TCS34725_RDATA  0x90
#define TCS34725_GDATA  0x94
#define TCS34725_BDATA  0x98

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(int fd) {
    if (i2c_write_reg8(fd, TCS34725_ENABLE, 0x01) < 0) return -1;
    usleep(3000);
    if (i2c_write_reg8(fd, TCS34725_ATIME, 0xFF) < 0) return -1;
    return 0;
}

static int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t c, r, g, b;
    if (i2c_read_reg8(fd, TCS34725_CDATA, &c) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_RDATA, &r) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_GDATA, &g) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_BDATA, &b) < 0) return -1;
    *clear = (uint16_t)c;
    *red   = (uint16_t)r;
    *green = (uint16_t)g;
    *blue  = (uint16_t)b;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", TCS34725_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "Error initializing TCS34725.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t clear, red, green, blue;
        if (tcs34725_read_data(fd, &clear, &red, &green, &blue) == 0) {
            printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }
        usleep(200000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_18 18
#define GPIO_21 21
#define GPIO_22 22

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line_18 = NULL;
static struct gpiod_line *line_21 = NULL;
static struct gpiod_line *line_22 = NULL;

static void cleanup_and_exit(int signum) {
    (void)signum;
    if (line_18) gpiod_line_release(line_18);
    if (line_21) gpiod_line_release(line_21);
    if (line_22) gpiod_line_release(line_22);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line_18 = gpiod_chip_get_line(chip, GPIO_18);
    line_21 = gpiod_chip_get_line(chip, GPIO_21);
    line_22 = gpiod_chip_get_line(chip, GPIO_22);
    if (!line_18 || !line_21 || !line_22) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(0);
        return 1;
    }

    if (gpiod_line_request_output(line_18, "gpio_control", 0) < 0 ||
        gpiod_line_request_output(line_21, "gpio_control", 0) < 0 ||
        gpiod_line_request_output(line_22, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(0);
        return 1;
    }

    if (gpiod_line_set_value(line_18, 1) < 0 ||
        gpiod_line_set_value(line_21, 1) < 0 ||
        gpiod_line_set_value(line_22, 1) < 0) {
        perror("gpiod_line_set_value");
        cleanup_and_exit(0);
        return 1;
