int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    if (!running) {
        fprintf(stderr, "Interrupted before write.\n");
        goto cleanup;
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value");
        goto cleanup;
    }

    printf("GPIO %d set HIGH\n", GPIO_LINE);
    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 8
static const unsigned int pins[NUM_PINS] = {1, 4, 5, 6, 21, 22, 23, 24};

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u): %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "gpio-control", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u): %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value(%u): %s\n", pins[i], strerror(errno));
                goto cleanup;
            }
            printf("GPIO %u: %s\n", pins[i], val ? "HIGH" : "LOW");
        }
        fflush(stdout);
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

static volatile sig_atomic_t stop = 0;

static void sigint_handler(int signo) {
    (void)signo;
    stop = 1;
}

static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);
    return r;
}

int main(void) {
    struct sigaction sa;
    CLEAR(sa);
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    const char *dev_name = "/dev/video0";
    int fd = open(dev_name, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", dev_name, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    CLEAR(cap);
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", dev_name);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", dev_name);
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    CLEAR(req);
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (MAP_FAILED == buffer) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    while (!stop) {
        fd_set fds;
        struct timeval tv;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = 2;
        tv.tv_usec = 0;

        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (-1 == r) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error in select: %s\n", strerror(errno));
            break;
        }
        if (0 == r) {
            fprintf(stderr, "select timeout\n");
            break;
        }

        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            break;
        }

        FILE *fp = fopen("image.yuv", "wb");
        if (!fp) {
            fprintf(stderr, "Error opening image.yuv: %s\n", strerror(errno));
            break;
        }

        size_t written = fwrite(buffer, 1, buf.bytesused, fp);
        if (written != buf.bytesused) {
            fprintf(stderr, "Short write: %zu of %u\n", written, buf.bytesused);
        }
        fclose(fp);

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error re-queuing buffer: %s\n", strerror(errno));
            break;
        }

        usleep(50000);
    }

    enum v4l2_buf_type type_off = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    xioctl(fd, VIDIOC_STREAMOFF, &type_off);
    munmap(buffer, buf.length);
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, uint8_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_calibration(int fd, uint16_t *dig_T1, int16_t *dig_T2, int16_t *dig_T3,
                            uint16_t *dig_P1, int16_t *dig_P2, int16_t *dig_P3,
                            int16_t *dig_P4, int16_t *dig_P5, int16_t *dig_P6,
                            int16_t *dig_P7, int16_t *dig_P8, int16_t *dig_P9) {
    uint8_t buf[26];
    if (i2c_read_block(fd, BME280_REG_CALIB_00, buf, 26) < 0) return -1;

    *dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    *dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    *dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    *dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    *dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    *dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    *dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    *dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    *dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    *dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    *dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    *dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));

    uint8_t buf2[7];
    if (i2c_read_block(fd, BME280_REG_CALIB_26, buf2, 7) < 0) return -1;
    *dig_T1 = (uint16_t)(buf2[0] | (buf2[1] << 8));
    *dig_T2 = (int16_t)(buf2[2] | (buf2[3] << 8));
    *dig_T3 = (int16_t)(buf2[4] | (buf2[5] << 8));
    return 0;
}

static int read_raw_data(int fd, int32_t *raw_temp, int32_t *raw_press, int32_t *raw_hum) {
    uint8_t buf[8];
    if (i2c_read_block(fd, BME280_REG_DATA, buf, 8) < 0) return -1;
    *raw_press = (int32_t)((buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4));
    *raw_temp = (int32_t)((buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4));
    *raw_hum = (int32_t)((buf[6] << 8) | buf[7]);
    return 0;
}

static double compensate_temperature(int32_t raw_temp, uint16_t dig_T1, int16_t dig_T2, int16_t dig_T3, int32_t *t_fine) {
    double var1 = ((double)raw_temp / 16384.0 - (double)dig_T1 / 1024.0) * (double)dig_T2;
    double var2 = ((double)raw_temp / 131072.0 - (double)dig_T1 / 8192.0) * ((double)raw_temp / 131072.0 - (double)dig_T1 / 8192.0) * (double)dig_T3;
    *t_fine = (int32_t)(var1 + var2);
    return (var1 + var2) / 5120.0;
}

static double compensate_pressure(int32_t raw_press, int32_t t_fine, uint16_t dig_P1, int16_t dig_P2, int16_t dig_P3, int16_t dig_P4, int16_t dig_P5, int16_t dig_P6, int16_t dig_P7, int16_t dig_P8, int16_t dig_P9) {
    double var1 = (double)t_fine / 2.0 - 64000.0;
    double var2 = var1 * var1 * (double)dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)dig_P5 * 2.0;
    var2 = var2 / 4.0 + (double)dig_P4 * 65536.0;
    var1 = ((double)dig_P3 * var1 * var1 / 524288.0 + (double)dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)dig_P1;
    if (var1 == 0.0) return 0.0;
    double p = 1048576.0 - (double)raw_press;
    p = (p - var2 / 4096.0) * 6250.0 / var1;
    var1 = (double)dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)dig_P7) / 16.0;
    return p;
}

static double compensate_humidity(int32_t raw_hum, int32_t t_fine, uint16_t dig_H1, int16_t dig_H2, int16_t dig_H3, int16_t dig_H4, int16_t dig_H5, int16_t dig_H6) {
    double var_H = (double)t_fine - 76800.0;
    var_H = (raw_hum - ((double)dig_H4 * 64.0 + (double)dig_H5 / 16384.0 * var_H)) * ((double)dig_H2 / 65536.0 * (1.0 + (double)dig_H6 / 67108864.0 * var_H * (1.0 + (double)dig_H3 / 67108864.0 * var_H)));
    var_H = var_H * (1.0 - (double)dig_H1 * var_H / 524288.0);
    if (var_H > 100.0) var_H = 100.0;
    if (var_H < 0.0) var_H = 0.0;
    return var_H;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address 0x%02X: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t chip_id;
    if (i2c_read_reg(fd, BME280_REG_ID, &chip_id) < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (chip_id != 0x60) {
        fprintf(stderr, "Invalid chip ID: 0x%02X (expected 0x60)\n", chip_id);
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, BME280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error resetting sensor: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    usleep(2000);

    uint16_t dig_T1;
    int16_t dig_T2, dig_T3, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
    uint16_t dig_H1;
    int16_t dig_H2, dig_H3, dig_H4, dig_H5, dig_H6;

    if (read_calibration(fd, &dig_T1, &dig_T2, &dig_T3, &dig_P1, &dig_P2, &dig_P3, &dig_P4, &dig_P5, &dig_P6, &dig_P7, &dig_P8, &dig_P9) < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, BME280_REG_CTRL_HUM, 0x01) < 0) {
        fprintf(stderr, "Error setting humidity oversampling: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (i2c_write_reg(fd, BME280_REG_CONFIG, 0xA0) < 0) {
        fprintf(stderr, "Error setting config register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (i2c_write_reg(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error setting ctrl_meas register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        uint8_t status;
        int timeout = 0;
        do {
            if (i2c_read_reg(fd, BME280_REG_STATUS, &status) < 0) {
                fprintf(stderr, "Error reading status register: %s\n", strerror(errno));
                close(fd);
                return 1;
            }
            usleep(2000);
            timeout++;
        } while ((status & 0x08) && timeout < 100 && running);

        if (timeout >= 100) {
            fprintf(stderr, "Timeout waiting for measurement\n");
            continue;
        }

        int32_t raw_temp, raw_press, raw_hum;
        if (read_raw_data(fd, &raw_temp, &raw_press, &raw_hum) < 0) {
            fprintf(stderr, "Error reading raw data: %s\n", strerror(errno));
            close(fd);
            return 1;
        }

        int32_t t_fine;
        double temp = compensate_temperature(raw_temp, dig_T1, dig_T2, dig_T3, &t_fine);
        double press = compensate_pressure(raw_press, t_fine, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9);
        double hum = compensate_humidity(raw_hum, t_fine, dig_H1, dig_H2, dig_H3, dig_H4, dig_H5, dig_H6);

        printf("Temperature: %.2f C, Pressure: %.2f hPa, Humidity: %.2f %%\n", temp, press / 100.0, hum);
        fflush(stdout);

        for (int i = 0; i < 5 && running; i++) {
            sleep(1);
        }
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

/* ADS1115 registers */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config register bits */
#define ADS1115_CFG_OS_BEGIN   (1 << 15)
#define ADS1115_CFG_MUX_AIN0   (0x4 << 12)  /* AIN0 vs GND */
#define ADS1115_CFG_PGA_4_096V (0x1 << 9)   /* +/-4.096 V */
#define ADS1115_CFG_MODE_SS   (0x0 << 8)    /* Single-shot */
#define ADS1115_CFG_DR_128    (0x4 << 5)    /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE (0x3 << 0)    /* Disable comparator */

static int i2c_fd = -1;

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write_reg16: write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write reg failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: read failed: %s\n", strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd)
{
    uint16_t config = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 |
                      ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SS |
                      ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE;
    return i2c_write_reg16(fd, ADS1115_REG_CONFIG, config);
}

static int ads1115_read_channel(int fd, uint16_t *raw)
{
    uint16_t config;
    if (i2c_read_reg16(fd, ADS1115_REG_CONFIG, &config) < 0)
        return -1;
    if (!(config & ADS1115_CFG_OS_BEGIN)) {
        fprintf(stderr, "ads1115_read_channel: conversion not complete\n");
        return -1;
    }
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, raw) < 0)
        return -1;
    return 0;
}

int main(void)
{
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (ads1115_init(i2c_fd) < 0) {
        fprintf(stderr, "ADS1115 initialization failed (device absent or bus error)\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t raw;
        if (ads1115_read_channel(i2c_fd, &raw) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(200000);
            continue;
        }
        printf("Raw ADC value: %u\n", raw);
        usleep(200000);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define INTERVAL_SEC 60

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value low */
    if (gpiod_line_request_output(line, "gpio-toggle", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("GPIO %d initialized as output (low).\n", GPIO_LINE);
    fflush(stdout);

    /* Main loop: toggle every 60 seconds */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        int new_val = val == 0 ? 1 : 0;
        if (gpiod_line_set_value(line, new_val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("GPIO %d toggled to %d\n", GPIO_LINE, new_val);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
