#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B

static int i2c_fd = -1;

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_accel_x(int fd, int16_t *x) {
    uint8_t high, low;
    if (i2c_read_reg8(fd, ACCEL_XOUT_H, &high) < 0) return -1;
    if (i2c_read_reg8(fd, ACCEL_XOUT_H + 1, &low) < 0) return -1;
    *x = (int16_t)((high << 8) | low);
    return 0;
}

int main(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (i2c_write_reg8(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error initializing MPU6050: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (1) {
        int16_t x;
        if (read_accel_x(i2c_fd, &x) < 0) {
            fprintf(stderr, "Error reading accelerometer X axis.\n");
            close(i2c_fd);
            return 1;
        }
        printf("Accel X: %d\n", x);
        usleep(10000);
    }

    close(i2c_fd);
    return 0;
}

