#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x27

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

void delay_ms(int ms) {
    usleep(ms * 1000);
}

void lcd_byte(int fd, int bits, int mode) {
    int high = (mode & 0x01) | ((bits & 0xF0) >> 4) | 0x04;
    int low = (mode & 0x01) | (bits & 0x0F) | 0x04;

    if (write(fd, &high, 1) != 1) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return;
    }
    delay_ms(2);
    if (write(fd, &low, 1) != 1) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return;
    }
    delay_ms(2);
}

void lcd_string(int fd, const char *s) {
    while (*s) {
        lcd_byte(fd, *s, 0x02);
        s++;
    }
}

void lcd_clear(int fd) {
    lcd_byte(fd, 0x01, 0x00);
    delay_ms(2);
}

void lcd_set_cursor(int fd, int col, int row) {
    int addr = (row == 0) ? 0x80 + col : 0xC0 + col;
    lcd_byte(fd, addr, 0x00);
}

int main() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    lcd_byte(fd, 0x33, 0x00);
    lcd_byte(fd, 0x32, 0x00);
    lcd_byte(fd, 0x28, 0x00);
    lcd_byte(fd, 0x0C, 0x00);
    lcd_byte(fd, 0x06, 0x00);
    lcd_clear(fd);

    while (running) {
        char buffer[17];
        snprintf(buffer, sizeof(buffer), "Hello, World!");
        lcd_clear(fd);
        lcd_set_cursor(fd, 0, 0);
        lcd_string(fd, buffer);
        sleep(10);
    }

    lcd_clear(fd);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t whoami;
    if (i2c_read_reg8(fd, 0x75, &whoami) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (whoami != 0x68) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x68, got 0x%02X\n", whoami);
        close(fd);
        return 1;
    }

    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    usleep(100000);

    for (int i = 0; i < 100 && running; i++) {
        int16_t ax, ay, az;
        if (i2c_read_reg16(fd, ACCEL_XOUT_H, &ax) < 0 ||
            i2c_read_reg16(fd, ACCEL_YOUT_H, &ay) < 0 ||
            i2c_read_reg16(fd, ACCEL_ZOUT_H, &az) < 0) {
            fprintf(stderr, "Failed to read accelerometer data: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", ax, ay, az);
        usleep(10000);
    }

    close(fd);
    return 0;
}

