#define TRIGGER_PIN 17
#define ECHO_PIN    22
#define SOUND_SPEED_CM_US 0.0343
#define MAX_DISTANCE_CM 400.0
#define MIN_DISTANCE_CM 2.0
#define TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static long elapsed_us(const struct timespec *start, const struct timespec *end) {
    return (long)(end->tv_sec - start->tv_sec) * 1000000L +
           (end->tv_nsec - start->tv_nsec) / 1000L;
}

static float read_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec t0, t1;
    long pulse_us;
    int val;

    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("set trigger low");
        return -1.0f;
    }
    usleep(2);
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("set trigger high");
        return -1.0f;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("set trigger low");
        return -1.0f;
    }

    clock_gettime(CLOCK_MONOTONIC, &t0);
    while ((val = gpiod_line_get_value(echo)) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &t1);
        if (elapsed_us(&t0, &t1) > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1.0f;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &t0);

    while ((val = gpiod_line_get_value(echo)) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &t1);
        if (elapsed_us(&t0, &t1) > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1.0f;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &t1);

    pulse_us = elapsed_us(&t0, &t1);
    float distance = (float)pulse_us * SOUND_SPEED_CM_US / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0f;
    }
    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("request trigger output");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("request echo input");
        goto cleanup;
    }

    while (running) {
        float dist = read_distance(trig, echo);
        if (dist < 0.0f) {
            fprintf(stderr, "Read failed, retrying...\n");
        } else {
            printf("Distance: %.2f cm\n", dist);
        }
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle every 1 second */
    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        int new_val = val == 0 ? 1 : 0;
        ret = gpiod_line_set_value(line, new_val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d: %s\n", GPIO_LINE, new_val ? "HIGH" : "LOW");
        fflush(stdout);

        sleep(1);
    }

    /* Clean up: set line low and release resources */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 18
#define GPIO_PIN_2 24

static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static struct gpiod_chip *chip = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line1) {
        gpiod_line_release(line1);
        line1 = NULL;
    }
    if (line2) {
        gpiod_line_release(line2);
        line2 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (1)");
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (2)");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line1, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output (1)");
        cleanup_and_exit(0);
        return 1;
    }

    if (gpiod_line_request_output(line2, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output (2)");
        cleanup_and_exit(0);
        return 1;
    }

    if (gpiod_line_set_value(line1, 1) < 0) {
        perror("gpiod_line_set_value (1)");
        cleanup_and_exit(0);
        return 1;
    }
    printf("GPIO %d set to HIGH\n", GPIO_PIN_1);

    if (gpiod_line_set_value(line2, 0) < 0) {
        perror("gpiod_line_set_value (2)");
        cleanup_and_exit(0);
        return 1;
    }
    printf("GPIO %d set to LOW\n", GPIO_PIN_2);

    cleanup_and_exit(0);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define GPIO_PIN_3 23
#define DELAY_SEC 2

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!line1 || !line2 || !line3) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, "gpio_control", 0) < 0 ||
        gpiod_line_request_output(line2, "gpio_control", 0) < 0 ||
        gpiod_line_request_output(line3, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (keep_running) {
        if (gpiod_line_set_value(line1, 1) < 0 ||
            gpiod_line_set_value(line2, 1) < 0 ||
            gpiod_line_set_value(line3, 1) < 0) {
            perror("gpiod_line_set_value high");
            goto cleanup;
        }
        printf("GPIO %d, %d, %d set HIGH\n", GPIO_PIN_1, GPIO_PIN_2, GPIO_PIN_3);
        fflush(stdout);

        sleep(DELAY_SEC);
        if (!keep_running) break;

        if (gpiod_line_set_value(line1, 0) < 0 ||
            gpiod_line_set_value(line2, 0) < 0 ||
            gpiod_line_set_value(line3, 0) < 0) {
            perror("gpiod_line_set_value low");
            goto cleanup;
        }
        printf("GPIO %d, %d, %d set LOW\n", GPIO_PIN_1, GPIO_PIN_2, GPIO_PIN_3);
        fflush(stdout);

        sleep(DELAY_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_TOPIC "sensor/data"
#define DEVICE_ID "rpi_sensor_1"
#define GPIO_PIN 4
#define SAMPLE_INTERVAL_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return value;
}

static int publish_data(MQTTClient client, const char *topic, int sensor_value) {
    char payload[64];
    int payload_len = snprintf(payload, sizeof(payload), "{\"device_id\": \"%s\", \"sensor_value\": %d}", DEVICE_ID, sensor_value);
    if (payload_len < 0 || (size_t)payload_len >= sizeof(payload)) {
        fprintf(stderr, "Error formatting payload\n");
        return -1;
    }

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    int rc = MQTTClient_publishMessage(client, topic, &pubmsg, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    MQTTClient client;
    int rc = MQTTClient_create(&client, MQTT_BROKER, DEVICE_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %s\n", MQTTClient_strerror(rc));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int sensor_value = read_sensor_data(GPIO_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor data. Exiting.\n");
            break;
        }

        if (publish_data(client, MQTT_TOPIC, sensor_value) != 0) {
            fprintf(stderr, "Error publishing data. Exiting.\n");
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define LOOP_DELAY_US 5000000  /* 5 seconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device may be absent).\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM on GPIO 18 */
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Warning: could not set exact PWM frequency on GPIO %d.\n", PWM_PIN);
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Warning: could not set exact PWM range on GPIO %d.\n", PWM_PIN);
    }

    /* Main loop: toggle PWM duty cycle every 5 seconds */
    while (running) {
        int duty = 0;
        if (gpioPWM(PWM_PIN, duty) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle on GPIO %d.\n", PWM_PIN);
            break;
        }
        printf("PWM duty cycle set to %d/255 (%d%%)\n", duty, (duty * 100) / PWM_RANGE);
        fflush(stdout);

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean shutdown: turn off PWM and release pigpio resources */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define CHIP_NAME   "gpiochip0"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec start, end;
    long long elapsed_ns;
    int ret;

    /* Ensure trigger is low for a clean pulse */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("Failed to set trigger low");
        return -1.0f;
    }
    usleep(2);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("Failed to set trigger high");
        return -1.0f;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("Failed to set trigger low");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout ~200 ms) */
    ret = gpiod_line_get_value(echo);
    if (ret < 0) {
        perror("Failed to read echo");
        return -1.0f;
    }
    while (ret == 0 && running) {
        ret = gpiod_line_get_value(echo);
        if (ret < 0) {
            perror("Failed to read echo");
            return -1.0f;
        }
        usleep(100);
    }
    if (!running) return -1.0f;
    if (ret == 0) {
        fprintf(stderr, "Timeout waiting for echo rising edge\n");
        return -1.0f;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    /* Wait for echo falling edge (timeout ~38 ms) */
    ret = gpiod_line_get_value(echo);
    if (ret < 0) {
        perror("Failed to read echo");
        return -1.0f;
    }
    while (ret == 1 && running) {
        ret = gpiod_line_get_value(echo);
        if (ret < 0) {
            perror("Failed to read echo");
            return -1.0f;
        }
        usleep(100);
    }
    if (!running) return -1.0f;
    if (ret == 1) {
        fprintf(stderr, "Timeout waiting for echo falling edge\n");
        return -1.0f;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL +
                 (end.tv_nsec - start.tv_nsec);

    /* Speed of sound ~343 m/s => 34300 cm/s => 0.0343 cm/us */
    return (float)elapsed_ns / 1000000000.0f * 34300.0f;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("Failed to get echo line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(trig, "hc-sr04-trig", 0);
    if (ret < 0) {
        perror("Failed to request trigger line as output");
        goto cleanup;
    }

    ret = gpiod_line_request_input(echo, "hc-sr04-echo");
    if (ret < 0) {
        perror("Failed to request echo line as input");
        goto cleanup;
    }

    while (running) {
        float distance = measure_distance(trig, echo);
        if (distance < 0.0f) {
            fprintf(stderr, "Measurement failed\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
        }
        usleep(200000);
    }

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int pins[] = {17, 18, 22, 23};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler\n");
    }

    while (running) {
        for (int i = 0; i < num_pins; i++) {
            int duty = (i + 1) * 50;
            if (duty > PWM_RANGE) duty = PWM_RANGE;
            if (gpioPWM(pins[i], duty) != 0) {
                fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", pins[i]);
            }
            printf("GPIO %d: PWM duty cycle = %d\n", pins[i], duty);
        }
        gpioDelay(DELAY_US);
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "sensor/data"
#define MQTT_CLIENT_ID "rpi_sensor_client"
#define MQTT_KEEPALIVE 60
#define SENSOR_READ_INTERVAL_SEC 5
#define SENSOR_TIMEOUT_SEC 2
#define MAX_RETRIES 3

#define SENSOR_GPIO_PIN 4
#define SENSOR_VALID_MIN 0.0
#define SENSOR_VALID_MAX 100.0

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(float *value) {
    int i;
    int level;
    struct timespec ts_start, ts_now;
    long elapsed_sec;

    if (gpioSetMode(SENSOR_GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", SENSOR_GPIO_PIN);
        return -1;
    }

    if (gpioWrite(SENSOR_GPIO_PIN, 1) < 0) {
        fprintf(stderr, "Error: Failed to write HIGH to GPIO %d\n", SENSOR_GPIO_PIN);
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &ts_start);

    for (i = 0; i < MAX_RETRIES; i++) {
        level = gpioRead(SENSOR_GPIO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: Failed to read GPIO %d (attempt %d)\n", SENSOR_GPIO_PIN, i + 1);
            return -1;
        }
        if (level == 1) {
            break;
        }
        gpioDelay(100000);
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        elapsed_sec = (ts_now.tv_sec - ts_start.tv_sec);
        if (elapsed_sec >= SENSOR_TIMEOUT_SEC) {
            fprintf(stderr, "Error: Sensor did not respond within %d seconds\n", SENSOR_TIMEOUT_SEC);
            return -1;
        }
    }

    if (i == MAX_RETRIES) {
        fprintf(stderr, "Error: Sensor did not become HIGH after %d retries\n", MAX_RETRIES);
        return -1;
    }

    gpioDelay(100000);

    level = gpioRead(SENSOR_GPIO_PIN);
    if (level < 0) {
        fprintf(stderr, "Error: Failed to read GPIO %d after settling\n", SENSOR_GPIO_PIN);
        return -1;
    }

    *value = (float)level * 100.0;
    return 0;
}

static int validate_sensor_data(float value) {
    if (value < SENSOR_VALID_MIN || value > SENSOR_VALID_MAX) {
        fprintf(stderr, "Warning: Sensor value %.2f out of range [%.2f, %.2f]\n",
                value, SENSOR_VALID_MIN, SENSOR_VALID_MAX);
        return -1;
    }
    return 0;
}

static int publish_data(struct mosquitto *mosq, float value) {
    char payload[64];
    int rc;

    snprintf(payload, sizeof(payload), "%.2f", value);

    rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC,
                           (int)strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: mosquitto_publish failed: %s\n", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

int main(void) {
    int rc;
    float sensor_value;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory creating mosquitto instance\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: mosquitto_connect failed: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: mosquitto_loop_start failed: %s\n", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (read_sensor_data(&sensor_value) == 0) {
            if (validate_sensor_data(sensor_value) == 0) {
                if (publish_data(mosq, sensor_value) != 0) {
                    fprintf(stderr, "Error: Failed to publish data\n");
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        for (int i = 0; i < SENSOR_READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    fprintf(stderr, "\nShutting down...\n");

    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/ads1115"
#define NUM_READINGS 10
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_ads1115(int handle, float *value) {
    char config[3];
    config[0] = CONFIG_REG;
    config[1] = 0xC3;
    config[2] = 0x83;
    if (i2cWriteDevice(handle, config, 3) < 0) return -1;
    gpioDelay(10000);
    char reg[1] = {CONVERSION_REG};
    if (i2cWriteDevice(handle, reg, 1) < 0) return -1;
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    int16_t raw = (buf[0] << 8) | buf[1];
    *value = (float)raw / 32768.0 * 6.0;
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    int handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2c open failed\n");
        gpioTerminate();
        return 1;
    }
    MQTTClient client;
    int rc = MQTTClient_create(&client, MQTT_BROKER, "ads1115_pub", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT create failed\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT connect failed\n");
        MQTTClient_destroy(&client);
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }
    for (int i = 0; i < NUM_READINGS && running; i++) {
        float val;
        if (read_ads1115(handle, &val) < 0) {
            fprintf(stderr, "Read failed\n");
            break;
        }
        char payload[20];
        snprintf(payload, sizeof(payload), "%.2f", val);
        MQTTClient_message msg = MQTTClient_message_initializer;
        msg.payload = payload;
        msg.payloadlen = (int)strlen(payload);
        msg.qos = 0;
        msg.retained = 0;
        MQTTClient_deliveryToken token;
        rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &msg, &token);
        if (rc != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Publish failed\n");
            break;
        }
        printf("Published: %s\n", payload);
        gpioDelay(1000000);
    }
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    i2cClose(handle);
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_18 18
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line GPIO_17");
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line GPIO_18");
        goto cleanup;
    }

    if (gpiod_line_request_output(line17, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output GPIO_17");
        goto cleanup;
    }

    if (gpiod_line_request_output(line18, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output GPIO_18");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line17, 1) < 0) {
            perror("gpiod_line_set_value GPIO_17");
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, 1) < 0) {
            perror("gpiod_line_set_value GPIO_18");
            goto cleanup;
        }
        printf("GPIO 17 and 18: HIGH\n");
        fflush(stdout);

        usleep(50000);

        if (gpiod_line_set_value(line17, 0) < 0) {
            perror("gpiod_line_set_value GPIO_17");
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, 0) < 0) {
            perror("gpiod_line_set_value GPIO_18");
            goto cleanup;
        }
        printf("GPIO 17 and 18: LOW\n");
        fflush(stdout);

        usleep(50000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, "gpio-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle every 5 seconds until interrupted */
    while (keep_running) {
        int current = gpiod_line_get_value(line);
        if (current < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        int new_value = !current;
        ret = gpiod_line_set_value(line, new_value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE, new_value);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_17 17
#define GPIO_PIN_23 23

static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line23 = NULL;
static struct gpiod_chip *chip = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line17) {
        gpiod_line_release(line17);
        line17 = NULL;
    }
    if (line23) {
        gpiod_line_release(line23);
        line23 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line17) {
        perror("gpiod_chip_get_line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    line23 = gpiod_chip_get_line(chip, GPIO_PIN_23);
    if (!line23) {
        perror("gpiod_chip_get_line 23");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line17, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output 17");
        cleanup_and_exit(0);
        return 1;
    }

    if (gpiod_line_request_output(line23, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output 23");
        cleanup_and_exit(0);
        return 1;
    }

    if (gpiod_line_set_value(line17, 1) < 0) {
        perror("gpiod_line_set_value 17");
        cleanup_and_exit(0);
        return 1;
    }
    printf("GPIO 17 set to HIGH\n");

    if (gpiod_line_set_value(line23, 0) < 0) {
        perror("gpiod_line_set_value 23");
        cleanup_and_exit(0);
        return 1;
    }
    printf("GPIO 23 set to LOW\n");

    cleanup_and_exit(0);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 22
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        int new_val = val ? 0 : 1;
        if (gpiod_line_set_value(line, new_val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE, new_val);
        fflush(stdout);

        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE B9600

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    int fd;
    struct termios tty;
    unsigned char buffer[256];
    ssize_t bytes_read;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening serial port");
        return EXIT_FAILURE;
    }

    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return EXIT_FAILURE;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        bytes_read = read(fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s\n", buffer);
            fflush(stdout);
        } else if (bytes_read == -1) {
            if (errno != EAGAIN && errno != EINTR) {
                perror("Error reading from serial port");
                break;
            }
        }
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B

static int i2c_fd = -1;

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        return -1;
    }
    return 0;
}

static int read_accel_data(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    if (i2c_read_reg16(fd, ACCEL_XOUT_H, ax) < 0) return -1;
    if (i2c_read_reg16(fd, ACCEL_XOUT_H + 2, ay) < 0) return -1;
    if (i2c_read_reg16(fd, ACCEL_XOUT_H + 4, az) < 0) return -1;
    return 0;
}

int main(void) {
    const char *dev = "/dev/i2c-1";
    i2c_fd = open(dev, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", dev, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    uint8_t whoami;
    if (i2c_read_reg8(i2c_fd, 0x75, &whoami) < 0) {
        fprintf(stderr, "Error: MPU6050 not detected at address 0x%02X.\n", MPU6050_ADDR);
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    int16_t ax, ay, az;
    while (1) {
        if (read_accel_data(i2c_fd, &ax, &ay, &az) == 0) {
            printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", ax, ay, az);
        } else {
            fprintf(stderr, "Error reading accelerometer data\n");
        }
        usleep(100000);
    }

    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_ADDR 0x76
#define I2C_DEV "/dev/i2c-1"

#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_calibration(int fd, uint16_t *dig_T1, int16_t *dig_T2, int16_t *dig_T3,
                            uint16_t *dig_P1, int16_t *dig_P2, int16_t *dig_P3,
                            int16_t *dig_P4, int16_t *dig_P5, int16_t *dig_P6,
                            int16_t *dig_P7, int16_t *dig_P8, int16_t *dig_P9) {
    uint8_t buf[24];
    if (i2c_read_block(fd, BMP280_REG_CALIB, buf, 24) < 0) return -1;
    *dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    *dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    *dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    *dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    *dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    *dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    *dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    *dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    *dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    *dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    *dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    *dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int read_raw(int fd, int32_t *raw_temp, int32_t *raw_press) {
    uint8_t buf[6];
    if (i2c_read_block(fd, BMP280_REG_PRESS_MSB, buf, 6) < 0) return -1;
    *raw_press = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
    *raw_temp = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | (buf[5] >> 4);
    return 0;
}

static double compensate_temp(int32_t raw_temp, uint16_t dig_T1, int16_t dig_T2, int16_t dig_T3, int32_t *t_fine) {
    int32_t var1, var2;
    var1 = ((((raw_temp >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    var2 = (((((raw_temp >> 4) - ((int32_t)dig_T1)) * ((raw_temp >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8;
}

static double compensate_press(int32_t raw_press, int32_t t_fine, uint16_t dig_P1, int16_t dig_P2, int16_t dig_P3, int16_t dig_P4, int16_t dig_P5, int16_t dig_P6, int16_t dig_P7, int16_t dig_P8, int16_t dig_P9) {
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)dig_P6;
    var2 = var2 + ((var1 * (int64_t)dig_P5) << 17);
    var2 = var2 + (((int64_t)dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)dig_P3) >> 8) + ((var1 * (int64_t)dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)dig_P1) >> 33;
    if (var1 == 0) return 0.0;
    p = 1048576 - raw_press;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)dig_P7) << 4);
    return (double)p / 256.0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BMP280_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t chip_id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &chip_id) < 0) {
        fprintf(stderr, "Failed to read chip ID: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (chip_id != 0x58) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x58). Not a BMP280.\n", chip_id);
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Failed to reset BMP280: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    usleep(2000);

    uint16_t dig_T1;
    int16_t dig_T2, dig_T3, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
    if (read_calibration(fd, &dig_T1, &dig_T2, &dig_T3, &dig_P1, &dig_P2, &dig_P3, &dig_P4, &dig_P5, &dig_P6, &dig_P7, &dig_P8, &dig_P9) < 0) {
        fprintf(stderr, "Failed to read calibration data: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x04 | (0x02 << 3)) < 0) {
        fprintf(stderr, "Failed to write config register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, (0x03 << 5) | (0x05 << 2) | 0x03) < 0) {
        fprintf(stderr, "Failed to write ctrl_meas register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        int32_t raw_temp, raw_press;
        if (read_raw(fd, &raw_temp, &raw_press) < 0) {
            fprintf(stderr, "Failed to read raw data: %s\n", strerror(errno));
            break;
        }

        int32_t t_fine;
        double temp_c = compensate_temp(raw_temp, dig_T1, dig_T2, dig_T3, &t_fine);
        double press_pa = compensate_press(raw_press, t_fine, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9);

        printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temp_c, press_pa);
        fflush(stdout);

        for (int i = 0; i < 5 && running; i++) {
            sleep(1);
        }
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 4
#define PWM_RANGE 255
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (device absent or permissions)\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty = 128;
    if (gpioPWM(PWM_PIN, duty) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM on GPIO %d: duty=%d/%d, freq=%d Hz\n",
           PWM_PIN, duty, PWM_RANGE, PWM_FREQ);
    fflush(stdout);

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 5
#define GPIO_PIN_2 6
#define GPIO_PIN_3 13

static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static struct gpiod_line *line3 = NULL;
static struct gpiod_chip *chip = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!line1 || !line2 || !line3) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(0);
        return 1;
    }

    if (gpiod_line_request_output(line1, "gpio_control", 0) < 0 ||
        gpiod_line_request_output(line2, "gpio_control", 0) < 0 ||
        gpiod_line_request_output(line3, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(0);
        return 1;
    }

    if (gpiod_line_set_value(line1, 1) < 0 ||
        gpiod_line_set_value(line2, 1) < 0 ||
        gpiod_line_set_value(line3, 1) < 0) {
        perror("gpiod_line_set_value");
        cleanup_and_exit(0);
        return 1;
    }

    printf("GPIO %d, %d, %d set to HIGH\n", GPIO_PIN_1, GPIO_PIN_2, GPIO_PIN_3);
    cleanup_and_exit(0);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_sensor_client"
#define MQTT_TOPIC "sensor/data"
#define GPIO_PIN 4
#define SAMPLE_INTERVAL_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int gpio_pin) {
    return gpioRead(gpio_pin);
}

static int publish_data(MQTTClient client, const char *topic, int data) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;

    char payload[20];
    int len = snprintf(payload, sizeof(payload), "%d", data);
    if (len < 0 || (size_t)len >= sizeof(payload)) {
        fprintf(stderr, "Error: Payload formatting failed.\n");
        return -1;
    }

    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    int rc = MQTTClient_publishMessage(client, topic, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        return -1;
    }
    return 0;
}

int main() {
    int rc;
    MQTTClient client;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    rc = MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID,
                           MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client, return code %d\n", rc);
        gpioTerminate();
        return 1;
    }

    rc = MQTTClient_connect(client, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int sensor_data = read_sensor_data(GPIO_PIN);
        if (sensor_data < 0) {
            fprintf(stderr, "Error reading sensor data\n");
        } else {
            if (publish_data(client, MQTT_TOPIC, sensor_data) != 0) {
                fprintf(stderr, "Error publishing data\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int pins[] = {2, 3, 18, 23, 24};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or permissions).\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 128) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("GPIO %d: PWM %d Hz, range %d, duty 128/255\n", pins[i], PWM_FREQUENCY, PWM_RANGE);
    }

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
