#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int pins[] = {17, 22, 27};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler\n");
    }

    while (running) {
        for (int i = 0; i < num_pins; i++) {
            int duty = (i + 1) * 50;
            if (gpioPWM(pins[i], duty) != 0) {
                fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", pins[i]);
            } else {
                printf("GPIO %d: PWM duty cycle = %d\n", pins[i], duty);
            }
        }
        gpioDelay(DELAY_US);
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

static int xioctl(int fd, int request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);
    return r;
}

int main(void)
{
    const char *dev_name = "/dev/video0";
    int fd = -1;
    char filename[64];
    struct {
        void   *start;
        size_t  length;
    } buffer;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    int ret = EXIT_FAILURE;

    fd = open(dev_name, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open '%s': %s\n", dev_name, strerror(errno));
        return EXIT_FAILURE;
    }

    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        if (EINVAL == errno) {
            fprintf(stderr, "%s is not a V4L2 device\n", dev_name);
        } else {
            fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        }
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", dev_name);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", dev_name);
        goto cleanup;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        goto cleanup;
    }

    CLEAR(req);
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        goto cleanup;
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        goto cleanup;
    }

    buffer.length = buf.length;
    buffer.start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (MAP_FAILED == buffer.start) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        buffer.start = NULL;
        goto cleanup;
    }

    if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        goto cleanup;
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        goto cleanup;
    }

    while (1) {
        fd_set fds;
        struct timeval tv;
        int r;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = 2;
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (-1 == r) {
            if (errno == EINTR) {
                break;
            }
            fprintf(stderr, "select error: %s\n", strerror(errno));
            goto cleanup;
        }
        if (0 == r) {
            fprintf(stderr, "select timeout\n");
            goto cleanup;
        }

        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
            if (errno == EAGAIN) {
                continue;
            }
            fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
            goto cleanup;
        }

        snprintf(filename, sizeof(filename), "image_%04d.jpg", 0);
        FILE *fp = fopen(filename, "wb");
        if (!fp) {
            fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
            goto cleanup;
        }

        if (fwrite(buffer.start, 1, buf.bytesused, fp) != buf.bytesused) {
            fprintf(stderr, "Write error: %s\n", strerror(errno));
            fclose(fp);
            goto cleanup;
        }

        fclose(fp);
        printf("Saved %s (%u bytes)\n", filename, buf.bytesused);

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            goto cleanup;
        }

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        if (buffer.start && buffer.start != MAP_FAILED) {
            munmap(buffer.start, buffer.length);
        }
        close(fd);
    }
    return ret;
}

/*
 * capture_image.c
 *
 * Captures a single image from the Raspberry Pi camera module using
 * the linux-v4l2 API.  Saves the image to a file.
 *
 * Build:  gcc -O2 -Wall -Wextra -o capture_image capture_image.c
 * Run:    ./capture_image [output_file]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEFAULT_DEVICE "/dev/video0"
#define DEFAULT_WIDTH   640
#define DEFAULT_HEIGHT  480
#define DEFAULT_FILE    "capture.jpg"

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int set_format(int fd, unsigned int width, unsigned int height,
                      unsigned int pixelformat)
{
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width       = width;
    fmt.fmt.pix.height      = height;
    fmt.fmt.pix.pixelformat = pixelformat;
    fmt.fmt.pix.field       = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    if (fmt.fmt.pix.width != width || fmt.fmt.pix.height != height) {
        fprintf(stderr, "Warning: driver adjusted size to %ux%u\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height);
    }
    return 0;
}

static int start_capturing(int fd)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

static int stop_capturing(int fd)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }
    return 0;
}

static int capture_frame(int fd, unsigned char *buffer, size_t buffer_size,
                         size_t *out_size)
{
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    if (buf.bytesused > buffer_size) {
        fprintf(stderr, "Buffer too small: got %u, have %zu\n",
                buf.bytesused, buffer_size);
        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0)
            perror("VIDIOC_QBUF");
        return -1;
    }

    memcpy(buffer, buf.m.planes[0].m.mmap, buf.bytesused);
    *out_size = buf.bytesused;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }
    return 0;
}

static int save_image(const char *filename, const unsigned char *data,
                      size_t size)
{
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    if (fwrite(data, 1, size, fp) != size) {
        perror("fwrite");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[])
{
    const char *device = DEFAULT_DEVICE;
    const char *filename = DEFAULT_FILE;
    unsigned int width = DEFAULT_WIDTH;
    unsigned int height = DEFAULT_HEIGHT;

    if (argc > 1) device = argv[1];
    if (argc > 2) filename = argv[2];
    if (argc > 3) {
        errno = 0;
        long w = strtol(argv[3], NULL, 10);
        if (errno != 0 || w < 1 || w > 8192) {
            fprintf(stderr, "Invalid width: %s\n", argv[3]);
            return EXIT_FAILURE;
        }
        width = (unsigned int)w;
    }
    if (argc > 4) {
        errno = 0;
        long h = strtol(argv[4], NULL, 10);
        if (errno != 0 || h < 1 || h > 8192) {
            fprintf(stderr, "Invalid height: %s\n", argv[4]);
            return EXIT_FAILURE;
        }
        height = (unsigned int)h;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (set_format(fd, width, height, V4L2_PIX_FMT_JPEG) < 0) {
        fprintf(stderr, "Failed to set format on %s\n", device);
        close(fd);
        return EXIT_FAILURE;
    }

    if (start_capturing(fd) < 0) {
        fprintf(stderr, "Failed to start capturing on %s\n", device);
        close(fd);
        return EXIT_FAILURE;
    }

    if (g_stop) {
        fprintf(stderr, "Interrupted before capture\n");
        stop_capturing(fd);
        close(fd);
        return EXIT_FAILURE;
    }

    size_t buffer_size = width * height * 3 / 2;
    unsigned char *buffer = malloc(buffer_size);
    if (!buffer) {
        perror("malloc");
        stop_capturing(fd);
        close(fd);
        return EXIT_FAILURE;
    }

    size_t image_size = 0;
    int rc = EXIT_FAILURE;

    if (capture_frame(fd, buffer, buffer_size, &image_size) == 0) {
        if (save_image(filename, buffer, image_size) == 0) {
            printf("Saved %zu bytes to %s\n", image_size, filename);
            rc = EXIT_SUCCESS;
        }
    } else {
        fprintf(stderr, "Failed to capture frame\n");
    }

    stop_capturing(fd);
    free(buffer);
    close(fd);
    return rc;
}

