#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define MAX_TIMINGS 85

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int level, int timeout_us) {
    int elapsed = 0;
    while (gpiod_line_get_value(line) != level) {
        if (!running) return -1;
        usleep(1);
        elapsed++;
        if (elapsed > timeout_us) return -2;
    }
    return elapsed;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int i, j;

    /* Start signal: pull low for >= 1 ms, then high for 20-40 us */
    if (gpiod_line_request_output(line, "dht22", 0) < 0) return -1;
    usleep(2000);
    gpiod_line_set_value(line, 1);
    usleep(30);

    /* Switch to input */
    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    /* Wait for sensor response: low then high */
    if (wait_for_level(line, 0, 100) < 0) return -1;
    if (wait_for_level(line, 1, 100) < 0) return -1;
    if (wait_for_level(line, 0, 100) < 0) return -1;

    /* Read 40 bits */
    for (i = 0; i < 5; i++) {
        for (j = 7; j >= 0; j--) {
            if (wait_for_level(line, 1, 100) < 0) return -1;
            int high_us = wait_for_level(line, 0, 100);
            if (high_us < 0) return -1;
            if (high_us > 40) {
                data[i] |= (1 << j);
            }
        }
    }

    /* Checksum */
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    *hum = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temp = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) *temp = -*temp;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temp, hum;

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (read_dht22(line, &temp, &hum) == 0) {
        printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
    } else {
        fprintf(stderr, "Failed to read DHT22\n");
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define CONSUMER "gpio_control"
#define DELAY_SEC 10

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4];
    unsigned int offsets[4] = {17, 23, 24, 25};
    int values[4] = {0, 1, 0, 1};
    int i;
    int ret = EXIT_FAILURE;

    /* Register signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    for (i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", offsets[i]);
            goto cleanup;
        }
    }

    /* Request lines as outputs, initial value LOW */
    for (i = 0; i < 4; i++) {
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", offsets[i]);
            goto cleanup;
        }
    }

    /* Main loop */
    while (running) {
        for (i = 0; i < 4; i++) {
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup;
            }
            printf("GPIO %u set to %d\n", offsets[i], values[i]);
        }
        fflush(stdout);

        /* Sleep for 10 seconds, checking running flag every second */
        for (i = 0; i < DELAY_SEC && running; i++) {
            sleep(1);
        }

        /* Toggle values for next iteration */
        for (i = 0; i < 4; i++) {
            values[i] = !values[i];
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    for (i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/mcp3008"
#define MCP3008_CS 8
#define MCP3008_CLK 10
#define MCP3008_DOUT 9
#define MCP3008_DIN 11

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char cmd = 0x01;
    unsigned char ch = (unsigned char)((channel & 0x07) << 4);
    unsigned char dummy = 0x00;
    unsigned char data[3];

    gpioWrite(MCP3008_CS, 0);
    gpioWrite(MCP3008_CLK, 0);

    for (int i = 0; i < 8; i++) {
        gpioWrite(MCP3008_CLK, 0);
        gpioWrite(MCP3008_DIN, (cmd >> (7 - i)) & 0x01);
        gpioDelay(1);
        gpioWrite(MCP3008_CLK, 1);
        gpioDelay(1);
    }

    for (int i = 0; i < 8; i++) {
        gpioWrite(MCP3008_CLK, 0);
        gpioWrite(MCP3008_DIN, (ch >> (7 - i)) & 0x01);
        gpioDelay(1);
        gpioWrite(MCP3008_CLK, 1);
        gpioDelay(1);
    }

    for (int i = 0; i < 8; i++) {
        gpioWrite(MCP3008_CLK, 0);
        gpioWrite(MCP3008_DIN, (dummy >> (7 - i)) & 0x01);
        gpioDelay(1);
        gpioWrite(MCP3008_CLK, 1);
        gpioDelay(1);
    }

    gpioWrite(MCP3008_CLK, 0);
    gpioDelay(1);
    gpioWrite(MCP3008_CLK, 1);
    gpioDelay(1);

    data[0] = gpioRead(MCP3008_DOUT);
    gpioWrite(MCP3008_CLK, 0);
    gpioDelay(1);
    gpioWrite(MCP3008_CLK, 1);
    gpioDelay(1);

    data[1] = gpioRead(MCP3008_DOUT);
    gpioWrite(MCP3008_CLK, 0);
    gpioDelay(1);
    gpioWrite(MCP3008_CLK, 1);
    gpioDelay(1);

    data[2] = gpioRead(MCP3008_DOUT);
    gpioWrite(MCP3008_CS, 1);

    int adc_value = ((data[0] & 0x03) << 10) | (data[1] << 2) | (data[2] >> 6);
    return adc_value;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioSetMode(MCP3008_CLK, PI_OUTPUT);
    gpioSetMode(MCP3008_DIN, PI_OUTPUT);
    gpioSetMode(MCP3008_DOUT, PI_INPUT);

    MQTTClient client;
    int rc;

    if ((rc = MQTTClient_create(&client, MQTT_BROKER, "mcp3008_publisher", MQTTCLIENT_PERSISTENCE_NONE, NULL)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client, return code %d\n", rc);
        gpioTerminate();
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            gpioDelay(1000000);
            continue;
        }

        char payload[20];
        snprintf(payload, sizeof(payload), "%d", adc_value);

        pubmsg.payload = payload;
        pubmsg.payloadlen = (int)strlen(payload);
        pubmsg.qos = 0;
        pubmsg.retained = 0;

        if ((rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token)) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        } else {
            printf("Published: %s\n", payload);
        }

        gpioDelay(1000000);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_FILE "image.jpg"
#define WIDTH 640
#define HEIGHT 480

static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);
    return r;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;
    FILE *fp = NULL;
    void *buffer = NULL;
    size_t buffer_size = 0;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Error opening device");
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        goto cleanup;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (MAP_FAILED == buffer) {
        perror("Error mapping buffer");
        buffer = NULL;
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        goto cleanup;
    }

    fp = fopen(IMAGE_FILE, "wb");
    if (!fp) {
        perror("Error opening image file");
        goto cleanup;
    }

    if (fwrite(buffer, 1, buf.bytesused, fp) != buf.bytesused) {
        perror("Error writing image data");
        goto cleanup;
    }

    printf("Image saved to %s (%zu bytes)\n", IMAGE_FILE, buf.bytesused);
    ret = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (buffer && buffer != MAP_FAILED) munmap(buffer, buffer_size);
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int pins[] = {4, 5, 6, 7, 8, 9};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < num_pins; i++) {
            int value = (i + 1) * 50;
            if (value > PWM_RANGE) value = PWM_RANGE;
            if (gpioPWM(pins[i], value) != 0) {
                fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("GPIO %d: PWM value = %d\n", pins[i], value);
        }
        gpioDelay(100000); /* 100 ms */
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
