            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value (18 on)");
            goto cleanup;
        }
        printf("Cycle %d: GPIO 17 and 18 ON\n", i + 1);
        fflush(stdout);
        sleep(1);

        if (!running) break;

        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value (17 off)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
