}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x27

// Segment display pins (common cathode)
#define SEG_A 0x01
#define SEG_B 0x02
#define SEG_C 0x04
#define SEG_D 0x08
#define SEG_E 0x10
#define SEG_F 0x20
#define SEG_G 0x40
#define SEG_DP 0x80

// Digit patterns for 0-9 (common cathode: 1 = segment ON)
static const uint8_t digits[] = {
    0x3F, // 0
    0x06, // 1
    0x5B, // 2
    0x4F, // 3
    0x66, // 4
    0x6D, // 5
    0x7D, // 6
    0x07, // 7
    0x7F, // 8
    0x6F  // 9
};

int main(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", PCF8574_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("I2C initialized on %s at address 0x%02X.\n", I2C_BUS, PCF8574_ADDR);

    while (1) {
        for (int i = 0; i < 10; i++) {
            uint8_t pattern = digits[i];
            if (write(fd, &pattern, 1) != 1) {
                fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
                close(fd);
                return EXIT_FAILURE;
            }
            printf("Displaying digit: %d\n", i);
            usleep(500000); // 0.5 seconds
        }
    }

    // Unreachable, but kept for completeness
    close(fd);
    return EXIT_SUCCESS;
}

