#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CHIP_NAME   "gpiochip0"

static volatile sig_atomic_t interrupted = 0;

static void sig_handler(int sig) {
    (void)sig;
    interrupted = 1;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
        perror("clock_gettime");
        return -1;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value");
        goto cleanup;
    }
    usleep(2000);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value");
        goto cleanup;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value");
        goto cleanup;
    }

    long long deadline = now_us() + 100000; /* 100 ms timeout */
    long long rise = -1, fall = -1;

    while (!interrupted) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }
        if (val == 1 && rise == -1) {
            rise = now_us();
        } else if (val == 0 && rise != -1 && fall == -1) {
            fall = now_us();
            break;
        }
        if (now_us() >= deadline) {
            fprintf(stderr, "Timeout waiting for echo pulse\n");
            goto cleanup;
        }
        usleep(10);
    }

    if (interrupted) {
        fprintf(stderr, "Interrupted\n");
        goto cleanup;
    }

    if (fall == -1) {
        fprintf(stderr, "No echo pulse received\n");
        goto cleanup;
    }

    long long diff = fall - rise;
    float distance = (float)diff / 58.0f;

    if (distance < 2.0f || distance > 400.0f) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        goto cleanup;
    }

    printf("Distance: %.2f cm\n", distance);
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 23
#define INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "gpio-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle every 5 seconds, exit on signal */
    while (keep_running) {
        int current = gpiod_line_get_value(line);
        if (current < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        int new_val = current ? 0 : 1;
        ret = gpiod_line_set_value(line, new_val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d toggled to %d\n", GPIO_LINE, new_val);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B

int main(void) {
    int file;
    char buffer[6];
    int16_t accel_x, accel_y, accel_z;

    file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(file);
        return EXIT_FAILURE;
    }

    if (write(file, (char[]){PWR_MGMT_1}, 1) != 1) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        close(file);
        return EXIT_FAILURE;
    }
    if (write(file, (char[]){0x00}, 1) != 1) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        close(file);
        return EXIT_FAILURE;
    }

    while (1) {
        if (write(file, (char[]){ACCEL_XOUT_H}, 1) != 1) {
            fprintf(stderr, "Error writing to ACCEL_XOUT_H: %s\n", strerror(errno));
            close(file);
            return EXIT_FAILURE;
        }
        if (read(file, buffer, 6) != 6) {
            fprintf(stderr, "Error reading from ACCEL_XOUT_H: %s\n", strerror(errno));
            close(file);
            return EXIT_FAILURE;
        }

        accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
        accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
        accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);

        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);
        fflush(stdout);

        usleep(100000);
    }

    close(file);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define GPIO_PIN_3 17
#define NUM_PINS 3
#define CYCLE_DELAY 5
#define NUM_CYCLES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    unsigned int offsets[NUM_PINS] = {GPIO_PIN_1, GPIO_PIN_2, GPIO_PIN_3};
    int values[NUM_PINS];
    int i, j;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
        values[i] = 0;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", offsets[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "gpio_control", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", offsets[i]);
            goto cleanup;
        }
    }

    for (j = 0; j < NUM_CYCLES && running; j++) {
        for (i = 0; i < NUM_PINS; i++) {
            values[i] = (values[i] == 0) ? 1 : 0;
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                fprintf(stderr, "Failed to set GPIO line %u\n", offsets[i]);
                goto cleanup;
            }
        }

        for (i = 0; i < NUM_PINS; i++) {
            int read_val = gpiod_line_get_value(lines[i]);
            if (read_val < 0) {
                fprintf(stderr, "Failed to read GPIO line %u\n", offsets[i]);
                goto cleanup;
            }
            if (read_val != values[i]) {
                fprintf(stderr, "Read/write mismatch on GPIO line %u: read %d, expected %d\n",
                        offsets[i], read_val, values[i]);
                goto cleanup;
            }
        }

        for (i = 0; i < NUM_PINS; i++) {
            printf("GPIO %u: %d\n", offsets[i], values[i]);
        }
        fflush(stdout);

        if (j < NUM_CYCLES - 1) {
            sleep(CYCLE_DELAY);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

