#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SHT31_ADDR 0x44
#define I2C_DEV "/dev/i2c-1"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, const uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int sht31_read(int fd, float *temperature, float *humidity) {
    uint8_t cmd[2] = {0x24, 0x00};
    uint8_t data[6];
    uint16_t raw_t, raw_h;

    if (i2c_write(fd, cmd, 2) < 0)
        return -1;

    usleep(20000);

    if (i2c_read(fd, data, 6) < 0)
        return -1;

    raw_t = ((uint16_t)data[0] << 8) | data[1];
    raw_h = ((uint16_t)data[3] << 8) | data[4];

    if (raw_t == 0xFFFF || raw_h == 0xFFFF) {
        fprintf(stderr, "SHT31 returned 0xFFFF (sensor absent or bus error)\n");
        return -1;
    }

    *temperature = -45.0f + 175.0f * (float)raw_t / 65535.0f;
    *humidity = 100.0f * (float)raw_h / 65535.0f;

    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "Temperature out of range: %.2f\n", *temperature);
        return -1;
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Humidity out of range: %.2f\n", *humidity);
        return -1;
    }

    return 0;
}

int main(void) {
    int fd = -1;
    float temperature, humidity;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SHT31_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        if (sht31_read(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read SHT31\n");
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++)
            sleep(1);
    }

    if (fd >= 0)
        close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 10
static const unsigned int pins[NUM_PINS] = {5, 6, 12, 16, 19, 20, 23, 24, 25, 26};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_PINS] = {NULL};
static volatile sig_atomic_t keep_running = 1;

static void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

static void release_resources(void) {
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pins[i]);
            release_resources();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "gpio_control", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO %u as output\n", pins[i]);
            release_resources();
            return EXIT_FAILURE;
        }
    }

    while (keep_running) {
        for (int i = 0; i < NUM_PINS; i++) {
            int val = (i % 2 == 0) ? 1 : 0;
            if (gpiod_line_set_value(lines[i], val) < 0) {
                fprintf(stderr, "Failed to set GPIO %u to %d\n", pins[i], val);
                release_resources();
                return EXIT_FAILURE;
            }
            printf("GPIO %u set to %d\n", pins[i], val);
        }
        sleep(1);
    }

    release_resources();
    return EXIT_SUCCESS;
}

