            goto cleanup;
        }
        printf("GPIO 17, 22, 27: HIGH\n");
        fflush(stdout);

        sleep(1);

        if (gpiod_line_set_value(line17, 0) < 0 ||
            gpiod_line_set_value(line22, 0) < 0 ||
            gpiod_line_set_value(line27, 0) < 0) {
            perror("gpiod_line_set_value LOW");
            goto cleanup;
        }
        printf("GPIO 17, 22, 27: LOW\n");
        fflush(stdout);

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line17) gpiod_line_release(line17);
    if (line22) gpiod_line_release(line22);
    if (line27) gpiod_line_release(line27);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int pins[] = {17, 18, 22, 27};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or permissions).\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 128) != 0) {
            fprintf(stderr, "Error: failed to start PWM on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("PWM on GPIO %d: ON (50%% duty cycle)\n", pins[i]);
    }

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
        printf("PWM on GPIO %d: OFF\n", pins[i]);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line1 || !line2) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output line1");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output line2");
        goto cleanup;
    }

