            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value line2");
            goto cleanup;
        }
        printf("GPIO %d and %d: HIGH\n", GPIO_PIN_1, GPIO_PIN_2);
        fflush(stdout);

        if (!running) break;

        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value line1");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value line2");
            goto cleanup;
        }
        printf("GPIO %d and %d: LOW\n", GPIO_PIN_1, GPIO_PIN_2);
        fflush(stdout);

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 17
#define INTERVAL_SEC 60

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 1)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 2)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line1, "gpio_toggle", 0) < 0) {
        perror("gpiod_line_request_output (pin 1)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "gpio_toggle", 0) < 0) {
        perror("gpiod_line_request_output (pin 2)");
        goto cleanup;
    }

    printf("GPIO %d and %d initialized as outputs (LOW).\n", GPIO_PIN_1, GPIO_PIN_2);
    fflush(stdout);

    /* Main loop: toggle every 60 seconds */
    while (keep_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);
        if (val1 < 0 || val2 < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        int new1 = !val1;
        int new2 = !val2;

        if (gpiod_line_set_value(line1, new1) < 0) {
            perror("gpiod_line_set_value (pin 1)");
            break;
        }
        if (gpiod_line_set_value(line2, new2) < 0) {
            perror("gpiod_line_set_value (pin 2)");
            break;
        }

        printf("GPIO %d -> %s, GPIO %d -> %s\n",
               GPIO_PIN_1, new1 ? "HIGH" : "LOW",
               GPIO_PIN_2, new2 ? "HIGH" : "LOW");
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);

    printf("\nResources released. Exiting.\n");
    return ret;
}

