#include <gpiod.h>

#define GPIO_18 18
#define GPIO_27 27
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line18 = NULL;
    struct gpiod_line *line27 = NULL;
