    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line GPIO 18");
        goto cleanup;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line27) {
        perror("gpiod_chip_get_line GPIO 27");
        goto cleanup;
    }

    if (gpiod_line_request_output(line18, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output GPIO 18");
        goto cleanup;
    }

    if (gpiod_line_request_output(line27, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output GPIO 27");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line18, 1) < 0) {
            perror("gpiod_line_set_value GPIO 18");
            goto cleanup;
        }
        if (gpiod_line_set_value(line27, 1) < 0) {
            perror("gpiod_line_set_value GPIO 27");
            goto cleanup;
        }
        printf("GPIO 18 and GPIO 27 set HIGH\n");
        fflush(stdout);

        usleep(10000);

        if (gpiod_line_set_value(line18, 0) < 0) {
            perror("gpiod_line_set_value GPIO 18");
            goto cleanup;
        }
        if (gpiod_line_set_value(line27, 0) < 0) {
            perror("gpiod_line_set_value GPIO 27");
            goto cleanup;
        }
        printf("GPIO 18 and GPIO 27 set LOW\n");
        fflush(stdout);

        usleep(10000);
    }

