#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 8
#define GPIO_PIN_2 17

static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static struct gpiod_chip *chip = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line1) {
        gpiod_line_release(line1);
        line1 = NULL;
    }
    if (line2) {
        gpiod_line_release(line2);
        line2 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 1)");
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 2)");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line1, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output (pin 1)");
        cleanup_and_exit(0);
        return 1;
    }

    if (gpiod_line_request_output(line2, "gpio_control", 1) < 0) {
        perror("gpiod_line_request_output (pin 2)");
        cleanup_and_exit(0);
        return 1;
    }

    int val1 = gpiod_line_get_value(line1);
    int val2 = gpiod_line_get_value(line2);
    if (val1 < 0 || val2 < 0) {
        perror("gpiod_line_get_value");
        cleanup_and_exit(0);
        return 1;
    }

    printf("GPIO %d: %d\n", GPIO_PIN_1, val1);
    printf("GPIO %d: %d\n", GPIO_PIN_2, val2);

    cleanup_and_exit(0);
    return 0;
}

