#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define W1_DIR "/sys/bus/w1/devices/"
#define MAX_DEVICES 10
#define MAX_PATH 256
#define READ_INTERVAL 5
#define NUM_READINGS 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int find_ds18b20(char *path, size_t path_size) {
    FILE *f = fopen(W1_DIR "w1_master_slaves", "r");
    if (!f) {
        fprintf(stderr, "Error opening w1_master_slaves: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    int found = 0;
    while (fgets(line, sizeof(line), f)) {
        line[strcspn(line, "\n")] = '\0';
        if (strncmp(line, "28-", 3) == 0) {
            snprintf(path, path_size, W1_DIR "%s/w1_slave", line);
            found = 1;
            break;
        }
    }
    fclose(f);

    if (!found) {
        fprintf(stderr, "No DS18B20 sensor found. Ensure it is connected to GPIO 4.\n");
        return -1;
    }
    return 0;
}

static float read_temperature(const char *path) {
    FILE *f = fopen(path, "r");
    if (!f) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1000.0f;
    }

    char line1[256];
    char line2[256];

    if (!fgets(line1, sizeof(line1), f) || !fgets(line2, sizeof(line2), f)) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        fclose(f);
        return -1000.0f;
    }
    fclose(f);

    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "CRC check failed on %s\n", path);
        return -1000.0f;
    }

    char *temp_str = strstr(line2, "t=");
    if (!temp_str) {
        fprintf(stderr, "Temperature data not found in %s\n", path);
        return -1000.0f;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    return (float)temp_raw / 1000.0f;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    char w1_path[MAX_PATH];
    if (find_ds18b20(w1_path, sizeof(w1_path)) != 0) {
        return EXIT_FAILURE;
    }

    printf("Reading DS18B20 temperature every %d seconds. Press Ctrl+C to exit.\n", READ_INTERVAL);

    for (int i = 0; i < NUM_READINGS && running; i++) {
        float temp = read_temperature(w1_path);
        if (temp > -999.0f) {
            printf("Reading %d: %.2f °C\n", i + 1, temp);
        } else {
            fprintf(stderr, "Error reading temperature (reading %d)\n", i + 1);
        }
        if (i < NUM_READINGS - 1 && running) {
            sleep(READ_INTERVAL);
        }
    }

    return EXIT_SUCCESS;
}

