    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", rc);
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        rc = gpioSetMode(pins[i], PI_OUTPUT);
        if (rc != 0) {
            fprintf(stderr, "gpioSetMode failed for pin %d: %d\n", pins[i], rc);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        int duty = 0;
        if (scanf("%d", &duty) != 1) {
            if (!running) break;
            fprintf(stderr, "Invalid input, skipping\n");
            int c;
            while ((c = getchar()) != '\n' && c != EOF) { /* discard */ }
            continue;
        }

        if (duty < 0 || duty > 100) {
            fprintf(stderr, "Duty cycle %d out of range [0, 100]\n", duty);
            continue;
        }

        int pwm_value = (duty * 255) / 100;

        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            rc = gpioPWM(pins[i], pwm_value);
            if (rc != 0) {
                fprintf(stderr, "gpioPWM failed for pin %d: %d\n", pins[i], rc);
            }
        }

        printf("PWM duty cycle set to %d%%\n", duty);
        fflush(stdout);

        usleep(100000); /* 0.1 s */
    }

    /* Release all PWM pins */
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

