        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", pins[i]);
            cleanup_and_exit(0);
        }
    }

    for (int i = 0; i < num_lines; i++) {
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", pins[i]);
            cleanup_and_exit(0);
