#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define MAX_TIMINGS 85
#define CYCLE_COUNT 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int level, uint64_t timeout_us) {
    uint64_t elapsed = 0;
    while (gpiod_line_get_value(line) != level) {
        if (!running) return -1;
        usleep(1);
        elapsed++;
        if (elapsed > timeout_us) return -2;
    }
    return 0;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int last_state = 1;
    uint64_t last_tick = 0;
    uint64_t timings[MAX_TIMINGS];
    int timing_idx = 0;

    // Send start signal
    gpiod_line_request_output(line, "dht22", 1);
    usleep(500000);
    gpiod_line_set_value(line, 0);
    usleep(20000);
    gpiod_line_set_value(line, 1);
    usleep(30);

    // Switch to input
    gpiod_line_request_input(line, "dht22");

    // Read data
    for (int i = 0; i < MAX_TIMINGS && timing_idx < 40; i++) {
        int ret = wait_for_level(line, !last_state, 100000);
        if (ret < 0) return ret;

        uint64_t tick = 0;
        while (gpiod_line_get_value(line) == last_state) {
            if (!running) return -1;
            usleep(1);
            tick++;
        }
        last_state = !last_state;

        if (i > 18 || (i % 2 == 0)) {
            timings[timing_idx++] = tick;
        }
    }

    if (timing_idx < 40) return -3;

    // Decode data
    for (int i = 0; i < 40; i++) {
        if (timings[i] > 50) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -4;
    }

    *hum = (float)((data[0] << 8) + data[1]) / 10.0f;
    *temp = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0f;
    if (data[2] & 0x80) *temp = -*temp;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = 1;

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    for (int i = 0; i < CYCLE_COUNT && running; i++) {
        float temp = 0.0f, hum = 0.0f;
        int rc = read_dht22(line, &temp, &hum);
        if (rc == 0) {
            printf("Cycle %d: Temperature = %.1f C, Humidity = %.1f %%\n", i + 1, temp, hum);
        } else {
            fprintf(stderr, "Cycle %d: Error reading DHT22 (code %d)\n", i + 1, rc);
            break;
        }
    }

    ret = 0;

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

