#include <signal.h>
#include <pigpio.h>

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define NUM_PINS 4
#define CYCLE_DELAY_US 60000000  /* 60 seconds in microseconds */

static const int pins[NUM_PINS] = {4, 17, 18, 27};
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_PINS; i++) {
        gpioPWM(pins[i], 0);
        gpioSetMode(pins[i], PI_INPUT);
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install signal handlers\n");
    }

    for (int cycle = 0; cycle < 5 && running; cycle++) {
        for (int i = 0; i < NUM_PINS; i++) {
            int duty = (cycle * 2 + i) % (PWM_RANGE + 1);
            if (gpioPWM(pins[i], duty) != 0) {
                fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", pins[i]);
                cleanup();
                return EXIT_FAILURE;
            }
            printf("GPIO %d: PWM duty cycle = %d/%d\n", pins[i], duty, PWM_RANGE);
        }
        fflush(stdout);

        if (cycle < 4 && running) {
            gpioDelay(CYCLE_DELAY_US);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 17
#define GPIO_PIN_2 27
#define INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 17)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 27)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line1, "gpio_toggle", 0) < 0) {
        perror("gpiod_line_request_output (pin 17)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "gpio_toggle", 0) < 0) {
        perror("gpiod_line_request_output (pin 27)");
        goto cleanup;
    }

    /* Main loop: toggle both lines every 5 seconds */
    while (keep_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);
        if (val1 < 0 || val2 < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        int new1 = !val1;
        int new2 = !val2;

        if (gpiod_line_set_value(line1, new1) < 0) {
            perror("gpiod_line_set_value (pin 17)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, new2) < 0) {
            perror("gpiod_line_set_value (pin 27)");
            goto cleanup;
        }

        printf("GPIO 17: %s, GPIO 27: %s\n", new1 ? "HIGH" : "LOW", new2 ? "HIGH" : "LOW");
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

