#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define CYCLE_DELAY 60
#define MAX_CYCLE 3
#define MAX_RETRIES 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

static void sleep_ms(unsigned int ms) {
    sleep_us(ms * 1000U);
}

static int wait_for_level(struct gpiod_line *line, int level, unsigned int timeout_us) {
    unsigned int waited = 0;
    while (gpiod_line_get_value(line) != level) {
        if (waited >= timeout_us) return -1;
        sleep_us(1);
        waited++;
    }
    return 0;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    unsigned char data[5] = {0};
    int i, j;

    for (i = 0; i < MAX_RETRIES; i++) {
        memset(data, 0, sizeof(data));

        if (gpiod_line_request_output(line, "dht22", 1) < 0) {
            fprintf(stderr, "Failed to request line as output: %s\n", strerror(errno));
            return -1;
        }
        gpiod_line_set_value(line, 1);
        sleep_ms(50);
        gpiod_line_set_value(line, 0);
        sleep_ms(20);
        gpiod_line_set_value(line, 1);

        if (gpiod_line_request_input(line, "dht22") < 0) {
            fprintf(stderr, "Failed to request line as input: %s\n", strerror(errno));
            return -1;
        }

        if (wait_for_level(line, 0, 1000) < 0) {
            fprintf(stderr, "DHT22 not responding (low timeout)\n");
            continue;
        }
        if (wait_for_level(line, 1, 1000) < 0) {
            fprintf(stderr, "DHT22 not responding (high timeout)\n");
            continue;
        }
        if (wait_for_level(line, 0, 1000) < 0) {
            fprintf(stderr, "DHT22 not responding (start bit timeout)\n");
            continue;
        }

        int valid = 1;
        for (j = 0; j < 40; j++) {
            if (wait_for_level(line, 1, 100) < 0) {
                valid = 0;
                break;
            }
            unsigned int count = 0;
            while (gpiod_line_get_value(line) == 1) {
                if (count > 100) { valid = 0; break; }
                sleep_us(1);
                count++;
            }
            if (!valid) break;
            if (count > 40) data[j / 8] |= (1 << (7 - (j % 8)));
        }

        if (!valid) {
            fprintf(stderr, "DHT22 read error on bit %d\n", j);
            continue;
        }

        unsigned char checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
        if (checksum != data[4]) {
            fprintf(stderr, "DHT22 checksum error: 0x%02X != 0x%02X\n", checksum, data[4]);
            continue;
        }

        unsigned int raw_hum = (data[0] << 8) | data[1];
        unsigned int raw_temp = (data[2] << 8) | data[3];
        if (raw_temp & 0x8000) {
            raw_temp = (raw_temp & 0x7FFF) * -1;
        }
        *hum = raw_hum / 10.0f;
        *temp = raw_temp / 10.0f;
        return 0;
    }
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temp, hum;
    int cycle = 0;

    struct sigaction sa = {
        .sa_handler = sig_handler,
        .sa_flags = 0
    };
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DHT22_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    while (running && cycle < MAX_CYCLE) {
        if (read_dht22(line, &temp, &hum) == 0) {
            printf("Cycle %d: Temperature = %.1f C, Humidity = %.1f %%\n", cycle + 1, temp, hum);
            fflush(stdout);
            cycle++;
        } else {
            fprintf(stderr, "Cycle %d: Failed to read DHT22\n", cycle + 1);
        }
        if (running && cycle < MAX_CYCLE) {
            sleep(CYCLE_DELAY);
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

