                goto cleanup;
            }
        }
        printf("State: %d %d %d %d\n", values[0], values[1], values[2], values[3]);
        fflush(stdout);
        usleep(100000); /* 0.1 seconds */
    }

cleanup:
    /* Release lines and close chip */
    for (i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
