/*
 * MAX31855 SPI temperature reader for Raspberry Pi
 * Uses spidev (Linux kernel character device).
 *
 * Wiring:
 *   MAX31855 VIN  -> Pi 3V3 (pin 1)
 *   MAX31855 GND  -> Pi GND (pin 6)
 *   MAX31855 SCLK -> Pi GPIO11 (pin 23, SPI0_SCLK)
 *   MAX31855 CS   -> Pi GPIO8  (pin 24, SPI0_CE0)
 *   MAX31855 DO   -> Pi GPIO9  (pin 21, SPI0_MISO)
 *
 * Build: gcc -O2 -Wall -o max31855 max31855.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    4000000U   /* 4 MHz — well within MAX31855 5 MHz limit */
#define SPI_BITS        8
#define SPI_DELAY_US    0

#define MAX31855_FAULT  0x00000000  /* No fault bit in the lower word */

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Read 4 bytes from the MAX31855.
 * Returns 0 on success, -1 on error.
 */
static int read_max31855(int fd, uint32_t *raw)
{
    uint8_t tx[4] = {0, 0, 0, 0};
    uint8_t rx[4] = {0, 0, 0, 0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    *raw = ((uint32_t)rx[0] << 24) |
           ((uint32_t)rx[1] << 16) |
           ((uint32_t)rx[2] <<  8) |
           ((uint32_t)rx[3]);
    return 0;
}

/*
 * Convert the 32-bit raw value to Celsius.
 * Returns true on success, false if the fault bit is set.
 */
static bool raw_to_celsius(uint32_t raw, float *celsius)
{
    if (raw == MAX31855_FAULT) {
        return false;
    }

    /*
     * The MAX31855 returns the thermocouple temperature in 0.25 °C steps
     * in the upper 14 bits of the 32-bit word.  The lower 16 bits hold
     * the internal (cold-junction) temperature in 0.0625 °C steps.
     *
     * The fault bit is the lowest bit of the lower 16-bit word.
     */
    int32_t tc_raw = (int32_t)(raw >> 18);          /* upper 14 bits */
    int32_t cj_raw = (int32_t)(raw & 0x3FFF);       /* lower 14 bits */

    /* Sign-extend the 14-bit thermocouple value */
    if (tc_raw & 0x2000) {
        tc_raw |= 0xFFFFC000;
    }

    /* Sign-extend the 14-bit cold-junction value */
    if (cj_raw & 0x2000) {
        cj_raw |= 0xFFFFC000;
    }

    *celsius = (float)tc_raw * 0.25f;
    return true;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() < 0) {
        goto cleanup;
    }

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        fprintf(stderr, "Ensure spi0 is enabled (raspi-config -> Interfacing Options -> SPI).\n");
        fprintf(stderr, "Then: sudo raspi-config --enable spi\n");
        goto cleanup;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        goto cleanup;
    }

    if (g_stop) {
        goto cleanup;
    }

    uint32_t raw = 0;
    if (read_max31855(fd, &raw) < 0) {
        fprintf(stderr, "MAX31855 read failed (device absent or bus error).\n");
        goto cleanup;
    }

    float celsius;
    if (!raw_to_celsius(raw, &celsius)) {
        fprintf(stderr, "MAX31855 fault detected (raw=0x%08X).\n", raw);
        goto cleanup;
    }

    printf("Temperature: %.2f °C\n", celsius);
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

