#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define CHIP_NAME "gpiochip0"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }

    /* Ensure trigger starts low */
    gpiod_line_set_value(trig, 0);
    usleep(2000);

    /* 10 µs trigger pulse */
    gpiod_line_set_value(trig, 1);
    usleep(10);
    gpiod_line_set_value(trig, 0);

    long long deadline = now_us() + 100000; /* 100 ms timeout */
    int val;
    long long rise = 0, fall = 0;

    /* Wait for echo rising edge */
    while (running) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value (rising)");
            goto cleanup;
        }
        if (val == 1) {
            rise = now_us();
            break;
        }
        if (now_us() >= deadline) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            goto cleanup;
        }
        usleep(10);
    }
    if (!running) goto cleanup;

    deadline = now_us() + 100000;
    while (running) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value (falling)");
            goto cleanup;
        }
        if (val == 0) {
            fall = now_us();
            break;
        }
        if (now_us() >= deadline) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            goto cleanup;
        }
        usleep(10);
    }
    if (!running) goto cleanup;

    long long diff = fall - rise;
    float distance = (float)diff / 58.0f;
    printf("Distance: %.2f cm\n", distance);
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

