    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "gpio-output", VALUE_MIN) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        int value = VALUE_MIN;
        if (gpiod_line_set_value(line, value) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("GPIO %d set to %d\n", GPIO_LINE, value);
        fflush(stdout);
        sleep(1);

        value = VALUE_MAX;
        if (gpiod_line_set_value(line, value) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("GPIO %d set to %d\n", GPIO_LINE, value);
        fflush(stdout);
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

#define BMP280_ADDR 0x03
#define I2C_DEV "/dev/i2c-1"

#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_ID 0xD0

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BMP280_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t chip_id;
    if (i2c_read_reg8(fd, BMP280_REG_ID, &chip_id) < 0) {
        fprintf(stderr, "Failed to read chip ID: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (chip_id != 0x58) {
        fprintf(stderr, "Unexpected chip ID: 0x%02X (expected 0x58)\n", chip_id);
        close(fd);
        return 1;
    }

    if (i2c_write_reg8(fd, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to write config register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_reg8(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Failed to write ctrl_meas register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    for (int i = 0; i < 3 && running; i++) {
        uint16_t raw_press, raw_temp;
        if (i2c_read_reg16(fd, BMP280_REG_PRESS_MSB, &raw_press) < 0 ||
            i2c_read_reg16(fd, BMP280_REG_TEMP_MSB, &raw_temp) < 0) {
            fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
            close(fd);
            return 1;
        }

        double temp = (double)raw_temp / 100.0;
        double press = (double)raw_press / 256.0;

        printf("Reading %d: Temperature = %.2f C, Pressure = %.2f Pa\n", i + 1, temp, press);
        fflush(stdout);

        if (i < 2) {
            for (int j = 0; j < 10 && running; j++) {
                usleep(100000);
            }
        }
    }

    close(fd);
    return 0;
}

