#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

static int32_t t_fine;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
} bme280_calib_data;

static bme280_calib_data calib;

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_calibration_data(int fd) {
    uint8_t buf[26];
    if (i2c_read_reg(fd, BME280_REG_CALIB_00, buf, 26) < 0) return -1;
    calib.dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    calib.dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    calib.dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    calib.dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    calib.dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    calib.dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    calib.dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    calib.dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    calib.dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    calib.dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    calib.dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    calib.dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    calib.dig_H1 = buf[25];

    uint8_t h_buf[7];
    if (i2c_read_reg(fd, BME280_REG_CALIB_26, h_buf, 7) < 0) return -1;
    calib.dig_H2 = (int16_t)(h_buf[0] | (h_buf[1] << 8));
    calib.dig_H3 = h_buf[2];
    calib.dig_H4 = (int16_t)((h_buf[3] << 4) | (h_buf[4] & 0x0F));
    calib.dig_H5 = (int16_t)((h_buf[5] << 4) | (h_buf[4] >> 4));
    calib.dig_H6 = (int8_t)h_buf[6];
    return 0;
}

static int32_t compensate_temperature(int32_t adc_T) {
    int32_t var1, var2, T;
    var1 = ((((adc_T >> 3) - ((int32_t)calib.dig_T1 << 1))) * ((int32_t)calib.dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)calib.dig_T1)) * ((adc_T >> 4) - ((int32_t)calib.dig_T1))) >> 12) * ((int32_t)calib.dig_T3)) >> 14;
    t_fine = var1 + var2;
    T = (t_fine * 5 + 128) >> 8;
    return T;
}

static uint32_t compensate_pressure(int32_t adc_P) {
    int32_t var1, var2;
    uint32_t p;
    var1 = ((int32_t)t_fine >> 1) - 64000;
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)calib.dig_P6);
    var2 = var2 + ((var1 * ((int32_t)calib.dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)calib.dig_P4) << 16);
    var1 = (((calib.dig_P3 * (((var1 >> 2) * (var1 >> 2)) >> 13)) >> 3) + ((((int32_t)calib.dig_P2) * var1) >> 1)) >> 18;
    var1 = ((((32768 + var1)) * ((int32_t)calib.dig_P1)) >> 15);
    if (var1 == 0) return 0;
    p = (((uint32_t)(((1048576) - adc_P) - (var2 >> 12))) * 3125);
    if (p < 0x80000000) p = (p << 1) / ((uint32_t)var1);
    else p = (p / (uint32_t)var1) * 2;
    var1 = (((int32_t)calib.dig_P9) * ((int32_t)(((p >> 3) * (p >> 3)) >> 13))) >> 12;
    var2 = (((int32_t)(p >> 2)) * ((int32_t)calib.dig_P8)) >> 13;
    p = (uint32_t)((int32_t)p + ((var1 + var2 + calib.dig_P7) >> 4));
    return p;
}

static int read_bme280_data(int fd, int32_t *temp, uint32_t *press) {
    uint8_t data[8];
    if (i2c_read_reg(fd, BME280_REG_DATA, data, 8) < 0) return -1;
    int32_t adc_P = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t adc_T = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    *temp = compensate_temperature(adc_T);
    *press = compensate_pressure(adc_P);
    return 0;
}

int main(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t id;
    if (i2c_read_reg(fd, BME280_REG_ID, &id, 1) < 0) {
        fprintf(stderr, "Failed to read BME280 ID: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (id != 0x60) {
        fprintf(stderr, "BME280 not found. ID read: 0x%02X\n", id);
        close(fd);
        return 1;
    }

    if (read_calibration_data(fd) < 0) {
        fprintf(stderr, "Failed to read calibration data: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, BME280_REG_CTRL_HUM, 0x01) < 0) {
        fprintf(stderr, "Failed to write CTRL_HUM: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (i2c_write_reg(fd, BME280_REG_CONFIG, 0xA0) < 0) {
        fprintf(stderr, "Failed to write CONFIG: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (i2c_write_reg(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Failed to write CTRL_MEAS: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    for (int i = 0; i < 3; i++) {
        int32_t temp;
        uint32_t press;
        if (read_bme280_data(fd, &temp, &press) < 0) {
            fprintf(stderr, "Failed to read BME280 data: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
        printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temp / 100.0, press);
        sleep(5);
    }

    close(fd);
    return 0;
}

