#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define VEML7700_ADDR 0x10
#define I2C_DEVICE "/dev/i2c-1"

#define VEML7700_REG_ALS_CONF 0x00
#define VEML7700_REG_ALS_DATA 0x04

#define VEML7700_ALS_CONF_DEFAULT 0x0000

static int i2c_fd = -1;

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

static int veml7700_init(int fd) {
    if (i2c_write_reg16(fd, VEML7700_REG_ALS_CONF, VEML7700_ALS_CONF_DEFAULT) < 0) {
        return -1;
    }
    usleep(10000);
    return 0;
}

static int veml7700_read_als(int fd, uint16_t *als_data) {
    return i2c_read_reg16(fd, VEML7700_REG_ALS_DATA, als_data);
}

int main(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (veml7700_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing VEML7700\n");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        uint16_t als_data = 0;
        if (veml7700_read_als(i2c_fd, &als_data) < 0) {
            fprintf(stderr, "Error reading ALS data\n");
            break;
        }
        printf("ALS: %u\n", als_data);
        fflush(stdout);
        usleep(500000);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <time.h>

#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE B9600
#define READ_TIMEOUT_SEC 1
#define POLL_INTERVAL_US 100000

static int serial_fd = -1;

static int init_serial(const char *port) {
    serial_fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (serial_fd < 0) {
        fprintf(stderr, "Error opening serial port %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(serial_fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(serial_fd);
        serial_fd = -1;
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag &= ~ICANON;
    tty.c_lflag &= ~ECHO;
    tty.c_lflag &= ~ECHOE;
    tty.c_lflag &= ~ECHONL;
    tty.c_lflag &= ~ISIG;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~OPOST;
    tty.c_oflag &= ~ONLCR;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1; /* 100ms inter-byte timeout */

    if (tcsetattr(serial_fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(serial_fd);
        serial_fd = -1;
        return -1;
    }

    tcflush(serial_fd, TCIOFLUSH);
    return 0;
}

static int read_serial(char *buf, size_t len) {
    ssize_t n = read(serial_fd, buf, len);
    if (n < 0) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0;
        }
        fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
        return -1;
    }
    return (int)n;
}

static void cleanup(void) {
    if (serial_fd >= 0) {
        close(serial_fd);
        serial_fd = -1;
    }
}

int main(void) {
    if (init_serial(SERIAL_PORT) != 0) {
        return EXIT_FAILURE;
    }

    printf("Serial port initialized. Reading data...\n");

    while (1) {
        char buffer[256];
        int bytes_read = read_serial(buffer, sizeof(buffer) - 1);

        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("%s", buffer);
            fflush(stdout);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from serial port.\n");
            cleanup();
            return EXIT_FAILURE;
        } else {
            /* No data available — check for device presence */
            struct timeval tv;
            fd_set rfds;
            FD_ZERO(&rfds);
            FD_SET(serial_fd, &rfds);
            tv.tv_sec = READ_TIMEOUT_SEC;
            tv.tv_usec = 0;

            int retval = select(serial_fd + 1, &rfds, NULL, NULL, &tv);
            if (retval == 0) {
                fprintf(stderr, "Device not responding. Exiting.\n");
                cleanup();
                return EXIT_FAILURE;
            } else if (retval < 0) {
                if (errno == EINTR) {
                    continue;
                }
                fprintf(stderr, "Error in select: %s\n", strerror(errno));
                cleanup();
                return EXIT_FAILURE;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CHIP_NAME   "gpiochip0"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Returns distance in cm, or -1.0 on error/timeout. */
static float read_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trig, 0)");
        return -1.0;
    }
    usleep(2000);

    /* 10 µs trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value(trig, 1)");
        return -1.0;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trig, 0)");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout ~200 ms) */
    int waited = 0;
    while (gpiod_line_get_value(echo) == 0) {
        usleep(100);
        if (++waited > 2000) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1.0;
        }
    }

    /* Measure echo high duration (timeout ~38 ms) */
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    waited = 0;
    while (gpiod_line_get_value(echo) == 1) {
        usleep(100);
        clock_gettime(CLOCK_MONOTONIC, &end);
        double elapsed = (end.tv_sec - start.tv_sec) +
                         (end.tv_nsec - start.tv_nsec) / 1e9;
        if (elapsed > 0.038) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1.0;
        }
        if (++waited > 380) {
            fprintf(stderr, "Timeout waiting for echo falling edge (loop)\n");
            return -1.0;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    double elapsed = (end.tv_sec - start.tv_sec) +
                     (end.tv_nsec - start.tv_nsec) / 1e9;

    /* distance = (speed_of_sound * elapsed) / 2 */
    float distance = (float)((34300.0 * elapsed) / 2.0);

    /* HC-SR04 range: 2 cm to 400 cm */
    if (distance < 2.0f || distance > 400.0f) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0;
    }

    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        float dist = read_distance(trig, echo);
        if (dist < 0.0f) {
            fprintf(stderr, "Read failed; skipping cycle.\n");
        } else {
            printf("Distance: %.2f cm\n", dist);
        }
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 8
#define DELAY_US 1000

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, "gpio-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle every 1 microsecond */
    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        int new_val = !val;
        ret = gpiod_line_set_value(line, new_val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d: %s\n", GPIO_LINE, new_val ? "HIGH" : "LOW");
        fflush(stdout);

        usleep(DELAY_US);
    }

    /* Clean up: set line low and release resources */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_BW_RATE 0x2C

static int fd = -1;

void cleanup(int sig) {
    (void)sig;
    if (fd >= 0) {
        close(fd);
        fd = -1;
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to acquire I2C bus access");
        close(fd);
        return 1;
    }

    // Set data rate to 100 Hz
    uint8_t bw_rate_val = 0x0A;
    if (write(fd, &(uint8_t){ADXL345_BW_RATE}, 1) != 1) {
        perror("Failed to write BW_RATE register address");
        close(fd);
        return 1;
    }
    if (write(fd, &bw_rate_val, 1) != 1) {
        perror("Failed to write BW_RATE value");
        close(fd);
        return 1;
    }

    // Enable measurement mode
    uint8_t power_ctl_val = 0x08;
    if (write(fd, &(uint8_t){ADXL345_POWER_CTL}, 1) != 1) {
        perror("Failed to write POWER_CTL register address");
        close(fd);
        return 1;
    }
    if (write(fd, &power_ctl_val, 1) != 1) {
        perror("Failed to write POWER_CTL value");
        close(fd);
        return 1;
    }

    // Read 6 bytes of data (X, Y, Z)
    uint8_t reg = ADXL345_DATAX0;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write DATAX0 register address");
        close(fd);
        return 1;
    }

    uint8_t data[6];
    if (read(fd, data, 6) != 6) {
        perror("Failed to read data from ADXL345");
        close(fd);
        return 1;
    }

    // Combine high and low bytes (little-endian)
    int16_t x = (int16_t)((data[1] << 8) | data[0]);
    int16_t y = (int16_t)((data[3] << 8) | data[2]);
    int16_t z = (int16_t)((data[5] << 8) | data[4]);

    printf("X: %d, Y: %d, Z: %d\n", x, y, z);

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
