#include <gpiod.h>

#define CONSUMER "gpio_control"
#define DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[8];
    unsigned int offsets[8] = {4, 17, 18, 22, 23, 24, 25, 27};
    int values[8] = {0, 0, 0, 0, 0, 0, 0, 0};
    int i;
    int ret;

    for (i = 0; i < 8; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", offsets[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < 8; i++) {
        ret = gpiod_line_request_output(lines[i], CONSUMER, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", offsets[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (i = 0; i < 8; i++) {
            values[i] = !values[i];
            ret = gpiod_line_set_value(lines[i], values[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to set GPIO line %u\n", offsets[i]);
                goto cleanup;
            }
            printf("GPIO %u: %s\n", offsets[i], values[i] ? "ON" : "OFF");
        }
        usleep(DELAY_US);
    }

cleanup:
    for (i = 0; i < 8; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_SUCCESS;
}

