#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 255
#define DELAY_US 100000  /* 0.1 seconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO 18 as PWM output */
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range to 255 for 8-bit resolution */
    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable PWM on the pin */
    if (gpioPWM(PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM output started on GPIO %d (range %d). Press Ctrl+C to exit.\n",
           PWM_PIN, PWM_RANGE);
    fflush(stdout);

    /* Main loop: toggle PWM duty cycle every 0.1 seconds */
    while (running) {
        if (gpioPWM(PWM_PIN, 128) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle.\n");
            break;
        }
        printf("PWM ON (duty cycle 128/255)\n");
        fflush(stdout);
        gpioDelay(DELAY_US);

        if (!running) break;

        if (gpioPWM(PWM_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle.\n");
            break;
        }
        printf("PWM OFF (duty cycle 0/255)\n");
        fflush(stdout);
        gpioDelay(DELAY_US);
    }

    /* Clean shutdown: turn off PWM and release pigpio resources */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nPWM output stopped.\n");
    return EXIT_SUCCESS;
}

