        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 2)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output (pin 1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output (pin 2)");
        goto cleanup;
    }

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value (pin 1 high)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value (pin 2 high)");
            goto cleanup;
        }
        printf("Cycle %d: GPIO %d and GPIO %d HIGH\n", i + 1, GPIO_PIN_1, GPIO_PIN_2);
        fflush(stdout);
        usleep(1000000);

        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value (pin 1 low)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value (pin 2 low)");
            goto cleanup;
        }
        printf("Cycle %d: GPIO %d and GPIO %d LOW\n", i + 1, GPIO_PIN_1, GPIO_PIN_2);
        fflush(stdout);
        usleep(1000000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_17 17
#define GPIO_PIN_21 21
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line21 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!line17) {
        perror("gpiod_chip_get_line (17)");
        goto cleanup;
    }
    line21 = gpiod_chip_get_line(chip, GPIO_PIN_21);
    if (!line21) {
        perror("gpiod_chip_get_line (21)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line17, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (17)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line21, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (21)");
        goto cleanup;
    }

    /* Main loop: toggle every 0.1 s until interrupted */
    while (keep_running) {
        int val17 = gpiod_line_get_value(line17);
        int val21 = gpiod_line_get_value(line21);
        if (val17 < 0 || val21 < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        int new17 = !val17;
        int new21 = !val21;

        if (gpiod_line_set_value(line17, new17) < 0) {
            perror("gpiod_line_set_value (17)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line21, new21) < 0) {
            perror("gpiod_line_set_value (21)");
            goto cleanup;
        }

        printf("GPIO 17: %d, GPIO 21: %d\n", new17, new21);
        fflush(stdout);

        usleep(100000); /* 0.1 s */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line17) gpiod_line_release(line17);
    if (line21) gpiod_line_release(line21);
    if (chip)   gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 4
#define PWM_RANGE 255
#define DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (int i = 0; i <= PWM_RANGE && running; i++) {
            if (gpioPWM(PWM_PIN, i) != 0) {
                fprintf(stderr, "Failed to set PWM duty cycle to %d\n", i);
                running = 0;
                break;
            }
            printf("PWM duty cycle: %d/%d\n", i, PWM_RANGE);
            fflush(stdout);
            gpioDelay(DELAY_US);
        }

        for (int i = PWM_RANGE; i >= 0 && running; i--) {
            if (gpioPWM(PWM_PIN, i) != 0) {
                fprintf(stderr, "Failed to set PWM duty cycle to %d\n", i);
                running = 0;
                break;
            }
            printf("PWM duty cycle: %d/%d\n", i, PWM_RANGE);
            fflush(stdout);
            gpioDelay(DELAY_US);
        }
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

