#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SOUND_SPEED_CM_PER_US 0.0343
#define MAX_DISTANCE_CM 400.0
#define MIN_DISTANCE_CM 2.0

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct gpiod_line_request_config trig_config = {
        .consumer = "hc-sr04-trig",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
    };
    struct gpiod_line_request_config echo_config = {
        .consumer = "hc-sr04-echo",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
    };

    if (gpiod_line_request(trig, &trig_config, 0) < 0) {
        perror("Failed to request trigger line");
        return -1.0;
    }
    if (gpiod_line_request(echo, &echo_config, 0) < 0) {
        perror("Failed to request echo line");
        gpiod_line_release(trig);
        return -1.0;
    }

    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("Failed to set trigger low");
        gpiod_line_release(trig);
        gpiod_line_release(echo);
        return -1.0;
    }
    usleep(2);

    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("Failed to set trigger high");
        gpiod_line_release(trig);
        gpiod_line_release(echo);
        return -1.0;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("Failed to set trigger low");
        gpiod_line_release(trig);
        gpiod_line_release(echo);
        return -1.0;
    }

    struct timespec start, end;
    long long start_ns, end_ns;
    int timeout = 0;

    while (gpiod_line_get_value(echo) == 0) {
        if (!running) break;
        usleep(1);
        timeout++;
        if (timeout > 100000) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            gpiod_line_release(trig);
            gpiod_line_release(echo);
            return -1.0;
        }
    }
    if (!running) {
        gpiod_line_release(trig);
        gpiod_line_release(echo);
        return -1.0;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

    timeout = 0;
    while (gpiod_line_get_value(echo) == 1) {
        if (!running) break;
        usleep(1);
        timeout++;
        if (timeout > 100000) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            gpiod_line_release(trig);
            gpiod_line_release(echo);
            return -1.0;
        }
    }
    if (!running) {
        gpiod_line_release(trig);
        gpiod_line_release(echo);
        return -1.0;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;

    long long diff_ns = end_ns - start_ns;
    float distance = (float)diff_ns * SOUND_SPEED_CM_PER_US / 2000.0;

    gpiod_line_release(trig);
    gpiod_line_release(echo);

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0;
    }
    return distance;
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("Failed to get echo line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float distance = measure_distance(trig, echo);
    if (distance < 0) {
        fprintf(stderr, "Error measuring distance\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Distance: %.2f cm\n", distance);

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

