        fprintf(stderr, "Failed to set SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set PWM pins as output
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM range (default is 255, but explicit for clarity)
    gpioSetPWMrange(PWM_PIN_1, 255);
    gpioSetPWMrange(PWM_PIN_2, 255);
    gpioSetPWMrange(PWM_PIN_3, 255);

    // Set PWM frequency (default is 1000 Hz, but explicit for clarity)
    gpioSetPWMfrequency(PWM_PIN_1, 1000);
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);

    // Set PWM duty cycle (0-255)
    gpioPWM(PWM_PIN_1, 100);
    gpioPWM(PWM_PIN_2, 150);
    gpioPWM(PWM_PIN_3, 200);

    printf("PWM pins set to 100, 150, 200 (range 0-255)\n");

    // Wait for signal to exit
    while (keep_running) {
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

