#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define CHIP_NAME "gpiochip0"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec start, end;
    long long elapsed_ns;
    int ret;

    /* Ensure trigger is low for a clean pulse */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("Failed to set trigger low");
        return -1.0f;
    }
    usleep(2);

    /* 10us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("Failed to set trigger high");
        return -1.0f;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("Failed to set trigger low");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout ~200ms) */
    ret = gpiod_line_get_value(echo);
    if (ret < 0) {
        perror("Failed to read echo");
        return -1.0f;
    }
    while (ret == 0) {
        ret = gpiod_line_get_value(echo);
        if (ret < 0) {
            perror("Failed to read echo");
            return -1.0f;
        }
        usleep(10);
        if (!running) return -1.0f;
    }
    clock_gettime(CLOCK_MONOTONIC, &start);

    /* Wait for echo falling edge (timeout ~38ms) */
    ret = gpiod_line_get_value(echo);
    if (ret < 0) {
        perror("Failed to read echo");
        return -1.0f;
    }
    while (ret == 1) {
        ret = gpiod_line_get_value(echo);
        if (ret < 0) {
            perror("Failed to read echo");
            return -1.0f;
        }
        usleep(10);
        if (!running) return -1.0f;
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL +
                 (end.tv_nsec - start.tv_nsec);

    /* Speed of sound ~343 m/s => 0.0343 cm/us; round-trip => divide by 2 */
    return (float)elapsed_ns / 2000000.0f;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("Failed to get GPIO lines");
        goto cleanup;
    }

    ret = gpiod_line_request_output(trig, "hc-sr04-trig", 0);
    if (ret < 0) {
        perror("Failed to request trigger line as output");
        goto cleanup;
    }

    ret = gpiod_line_request_input(echo, "hc-sr04-echo");
    if (ret < 0) {
        perror("Failed to request echo line as input");
        goto cleanup;
    }

    while (running) {
        float distance = measure_distance(trig, echo);
        if (distance < 0.0f) {
            fprintf(stderr, "Measurement failed\n");
            break;
        }
        printf("Distance: %.2f cm\n", distance);
        usleep(100000);
    }

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 16
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN, PWM_RANGE / 2) != 0) {
        fprintf(stderr, "Error: failed to set PWM duty cycle on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM output on GPIO %d set to 50%% duty cycle (range %d, value %d)\n",
           PWM_PIN, PWM_RANGE, PWM_RANGE / 2);
    fflush(stdout);

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("PWM output on GPIO %d stopped and pigpio terminated.\n", PWM_PIN);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_ADDR 0x29
#define I2C_DEV "/dev/i2c-1"

#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME  0x81
#define TCS34725_CDATA  0x8C
#define TCS34725_RDATA  0x90
#define TCS34725_GDATA  0x94
#define TCS34725_BDATA  0x98

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(int fd) {
    if (i2c_write_reg8(fd, TCS34725_ENABLE, 0x01) < 0) return -1;
    usleep(3000);
    if (i2c_write_reg8(fd, TCS34725_ATIME, 0xFF) < 0) return -1;
    return 0;
}

static int tcs34725_read_data(int fd, uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    uint8_t c_lo, c_hi, r_lo, r_hi, g_lo, g_hi, b_lo, b_hi;
    if (i2c_read_reg8(fd, TCS34725_CDATA, &c_lo) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_CDATA + 1, &c_hi) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_RDATA, &r_lo) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_RDATA + 1, &r_hi) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_GDATA, &g_lo) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_GDATA + 1, &g_hi) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_BDATA, &b_lo) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_BDATA + 1, &b_hi) < 0) return -1;
    *c = (uint16_t)((c_hi << 8) | c_lo);
    *r = (uint16_t)((r_hi << 8) | r_lo);
    *g = (uint16_t)((g_hi << 8) | g_lo);
    *b = (uint16_t)((b_hi << 8) | b_lo);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TCS34725_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed (device absent or bus error).\n");
        close(fd);
        return 1;
    }

    printf("TCS34725 initialized. Reading every 0.5 seconds. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t c, r, g, b;
        if (tcs34725_read_data(fd, &c, &r, &g, &b) == 0) {
            printf("C: %5u, R: %5u, G: %5u, B: %5u\n", c, r, g, b);
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }
        usleep(500000);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return 0;
}

