            fprintf(stderr, "Failed to get GPIO line %u\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], "gpio_control", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < NUM_PINS; i++) {
        int val = (i % 2 == 0) ? 1 : 0;
        if (gpiod_line_set_value(lines[i], val) < 0) {
            fprintf(stderr, "Failed to set GPIO line %u\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
