#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 255
#define DELAY_US 200000  /* 0.2 seconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM pin as output */
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range (number of steps) */
    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency to 1 kHz (default on most pins) */
    if (gpioSetPWMfrequency(PWM_PIN, 1000) != 0) {
        fprintf(stderr, "Warning: failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        /* Non-fatal: continue with default 1 MHz divisor */
    }

    /* Main loop: toggle PWM duty cycle every 0.2 seconds */
    while (running) {
        /* Duty cycle 0 -> 0%, 128 -> 50%, 255 -> 100% */
        int duty = 128;
        if (gpioPWM(PWM_PIN, duty) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle on GPIO %d.\n", PWM_PIN);
            break;
        }
        printf("PWM duty cycle set to %d (%.1f%%)\n", duty, (duty / (float)PWM_RANGE) * 100.0);
        fflush(stdout);

        /* Wait 0.2 seconds */
        gpioDelay(DELAY_US);
    }

    /* Clean shutdown: turn PWM off and release pigpio resources */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("PWM stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 17
#define GPIO_PIN_2 18

static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static struct gpiod_chip *chip = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (line1) {
        gpiod_line_set_value(line1, 0);
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_set_value(line2, 0);
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line 18");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line1, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output 17");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line2, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output 18");
        gpiod_line_set_value(line1, 0);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_value(line1, 1) < 0) {
        perror("gpiod_line_set_value 17");
        cleanup_and_exit(0);
    }
    printf("GPIO 17 set to HIGH\n");

    if (gpiod_line_set_value(line2, 1) < 0) {
        perror("gpiod_line_set_value 18");
        cleanup_and_exit(0);
    }
    printf("GPIO 18 set to HIGH\n");

    cleanup_and_exit(0);
    return 0;
}

